  1→'use client';
  2→
  3→import { Button } from '@tpmjs/ui/Button/Button';
  4→import { Icon, type IconName } from '@tpmjs/ui/Icon/Icon';
  5→import Link from 'next/link';
  6→import { usePathname, useRouter } from 'next/navigation';
  7→import { useEffect, useState } from 'react';
  8→import { useSession } from '@/lib/auth-client';
  9→import { AppHeader } from '../AppHeader';
 10→
 11→interface NavItem {
 12→  href: string;
 13→  label: string;
 14→  icon: IconName;
 15→  badge?: number;
 16→}
 17→
 18→interface NavSection {
 19→  title?: string;
 20→  items: NavItem[];
 21→}
 22→
 23→const navSections: NavSection[] = [
 24→  {
 25→    items: [
 26→      { href: '/dashboard', label: 'Overview', icon: 'home' },
 27→      { href: '/dashboard/activity', label: 'Activity', icon: 'barChart' },
 28→      { href: '/dashboard/agents', label: 'Agents', icon: 'terminal' },
 29→      { href: '/dashboard/collections', label: 'Collections', icon: 'folder' },
 30→      { href: '/dashboard/memories', label: 'Memories', icon: 'database' },
 31→    ],
 32→  },
 33→  {
 34→    title: 'Settings',
 35→    items: [
 36→      { href: '/dashboard/settings/profile', label: 'Profile', icon: 'user' },
 37→      { href: '/dashboard/settings/api-keys', label: 'AI Provider Keys', icon: 'puzzle' },
 38→      { href: '/dashboard/settings/tpmjs-api-keys', label: 'Platform API Keys', icon: 'key' },
 39→      { href: '/dashboard/settings/bridge', label: 'Bridge', icon: 'link' },
 40→      { href: '/dashboard/usage', label: 'Usage', icon: 'globe' },
 41→    ],
 42→  },
 43→];
 44→
 45→const adminNavItems: NavItem[] = [
 46→  { href: '/dashboard/admin', label: 'Overview', icon: 'barChart' },
 47→  { href: '/dashboard/admin/users', label: 'Users', icon: 'user' },
 48→];
 49→
 50→const likesNavItems: NavItem[] = [
 51→  { href: '/dashboard/likes/tools', label: 'Tools', icon: 'puzzle' },
 52→  { href: '/dashboard/likes/collections', label: 'Collections', icon: 'folder' },
 53→  { href: '/dashboard/likes/agents', label: 'Agents', icon: 'terminal' },
 54→];
 55→
 56→interface DashboardLayoutProps {
 57→  children: React.ReactNode;
 58→  /** Title displayed in the header */
 59→  title: string;
 60→  /** Optional subtitle/description */
 61→  subtitle?: string;
 62→  /** Action buttons for the header */
 63→  actions?: React.ReactNode;
 64→  /** Whether to show back button */
 65→  showBackButton?: boolean;
 66→  /** Custom back URL (defaults to parent route) */
 67→  backUrl?: string;
 68→  /** Whether to use full height layout (for chat interfaces) - removes padding and fills viewport */
 69→  fullHeight?: boolean;
 70→}
 71→
 72→export function DashboardLayout({
 73→  children,
 74→  title,
 75→  subtitle,
 76→  actions,
 77→  showBackButton,
 78→  backUrl,
 79→  fullHeight,
 80→}: DashboardLayoutProps): React.ReactElement {
 81→  const pathname = usePathname();
 82→  const router = useRouter();
 83→  const { data: session, isPending } = useSession();
 84→  const [sidebarOpen, setSidebarOpen] = useState(false);
 85→  const [isAdminUser, setIsAdminUser] = useState(false);
 86→  const [likesExpanded, setLikesExpanded] = useState(() => {
 87→    if (typeof window !== 'undefined') {
 88→      const stored = localStorage.getItem('dashboard-likes-expanded');
 89→      return stored === 'true';
 90→    }
 91→    return false;
 92→  });
 93→
 94→  // Persist likes expanded state
 95→  useEffect(() => {
 96→    localStorage.setItem('dashboard-likes-expanded', String(likesExpanded));
 97→  }, [likesExpanded]);
 98→
 99→  // Auto-expand if on a likes page - intentional route-based UI sync
100→  useEffect(() => {
101→    if (pathname.startsWith('/dashboard/likes')) {
102→      // eslint-disable-next-line react-hooks/set-state-in-effect
103→      setLikesExpanded(true);
104→    }
105→  }, [pathname]);
106→
107→  // Redirect to sign-in if not authenticated
108→  useEffect(() => {
109→    if (!isPending && !session) {
110→      router.push('/sign-in');
111→    }
112→  }, [isPending, session, router]);
113→
114→  // Check admin status
115→  useEffect(() => {
116→    if (session?.user?.id) {
117→      fetch('/api/admin/stats', { method: 'GET' })
118→        .then((res) => setIsAdminUser(res.ok))
119→        .catch(() => setIsAdminUser(false));
120→    }
121→  }, [session?.user?.id]);
122→
123→  // Close sidebar on route change - intentional route-based UI sync
124→  // biome-ignore lint/correctness/useExhaustiveDependencies: pathname triggers effect
125→  useEffect(() => {
126→    // eslint-disable-next-line react-hooks/set-state-in-effect
127→    setSidebarOpen(false);
128→  }, [pathname]);
129→
130→  const isActive = (href: string) => {
131→    if (href === '/dashboard') {
132→      return pathname === '/dashboard';
133→    }
134→    return pathname.startsWith(href);
135→  };
136→
137→  const isLikesActive = pathname.startsWith('/dashboard/likes');
138→
139→  const getBackUrl = () => {
140→    if (backUrl) return backUrl;
141→    // Get parent route
142→    const parts = pathname.split('/').filter(Boolean);
143→    parts.pop();
144→    return parts.length > 0 ? `/${parts.join('/')}` : '/dashboard';
145→  };
146→
147→  if (isPending) {
148→    return (
149→      <div className="min-h-screen bg-background">
150→        <AppHeader />
151→        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
152→          <div className="animate-pulse text-foreground-secondary">Loading...</div>
153→        </div>
154→      </div>
155→    );
156→  }
157→
158→  if (!session) {
159→    return <div />;
160→  }
161→
162→  return (
163→    <div className="min-h-screen bg-background">
164→      <AppHeader />
165→
166→      <div className="flex">
167→        {/* Mobile sidebar backdrop */}
168→        {sidebarOpen && (
169→          <button
170→            type="button"
171→            className="fixed inset-0 bg-black/50 z-40 lg:hidden cursor-default"
172→            onClick={() => setSidebarOpen(false)}
173→            aria-label="Close sidebar"
174→          />
175→        )}
176→
177→        {/* Sidebar */}
178→        <aside
179→          className={`
180→            fixed lg:sticky top-16 left-0 z-50 lg:z-0
181→            w-64 h-[calc(100vh-64px)] bg-background border-r border-border
182→            transform transition-transform lg:transform-none
183→            ${sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
184→          `}
185→        >
186→          <nav className="p-4 space-y-6 overflow-y-auto h-[calc(100%-80px)]">
187→            {navSections.map((section, sectionIdx) => (
188→              <div key={section.title || `section-${sectionIdx}`}>
189→                {section.title && (
190→                  <h3 className="px-3 mb-2 text-xs font-semibold text-foreground-tertiary uppercase tracking-wider">
191→                    {section.title}
192→                  </h3>
193→                )}
194→                <div className="space-y-1">
195→                  {section.items.map((item) => (
196→                    <Link
197→                      key={item.href}
198→                      href={item.href}
199→                      className={`
200→                        flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors
201→                        ${
202→                          isActive(item.href)
203→                            ? 'bg-primary/10 text-primary'
204→                            : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
205→                        }
206→                      `}
207→                    >
208→                      <Icon icon={item.icon} size="sm" />
209→                      <span>{item.label}</span>
210→                      {item.badge !== undefined && item.badge > 0 && (
211→                        <span className="ml-auto text-xs bg-surface-secondary px-1.5 py-0.5 rounded-full">
212→                          {item.badge}
213→                        </span>
214→                      )}
215→                    </Link>
216→                  ))}
217→                </div>
218→              </div>
219→            ))}
220→
221→            {/* Likes Section - Collapsible */}
222→            <div>
223→              <button
224→                type="button"
225→                onClick={() => setLikesExpanded(!likesExpanded)}
226→                className={`
227→                  w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors
228→                  ${
229→                    isLikesActive
230→                      ? 'bg-primary/10 text-primary'
231→                      : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
232→                  }
233→                `}
234→              >
235→                <Icon icon="heart" size="sm" />
236→                <span>Likes</span>
237→                <Icon
238→                  icon={likesExpanded ? 'chevronDown' : 'chevronRight'}
239→                  size="xs"
240→                  className="ml-auto"
241→                />
242→              </button>
243→
244→              {likesExpanded && (
245→                <div className="ml-4 mt-1 space-y-1">
246→                  {likesNavItems.map((item) => (
247→                    <Link
248→                      key={item.href}
249→                      href={item.href}
250→                      className={`
251→                        flex items-center gap-3 px-3 py-1.5 rounded-lg text-sm transition-colors
252→                        ${
253→                          isActive(item.href)
254→                            ? 'bg-primary/10 text-primary font-medium'
255→                            : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
256→                        }
257→                      `}
258→                    >
259→                      <Icon icon={item.icon} size="xs" />
260→                      <span>{item.label}</span>
261→                    </Link>
262→                  ))}
263→                </div>
264→              )}
265→            </div>
266→
267→            {/* Admin Section - only shown for admin users */}
268→            {isAdminUser && (
269→              <div>
270→                <h3 className="px-3 mb-2 text-xs font-semibold text-foreground-tertiary uppercase tracking-wider">
271→                  Admin
272→                </h3>
273→                <div className="space-y-1">
274→                  {adminNavItems.map((item) => (
275→                    <Link
276→                      key={item.href}
277→                      href={item.href}
278→                      className={`
279→                        flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors
280→                        ${
281→                          isActive(item.href)
282→                            ? 'bg-primary/10 text-primary'
283→                            : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
284→                        }
285→                      `}
286→                    >
287→                      <Icon icon={item.icon} size="sm" />
288→                      <span>{item.label}</span>
289→                    </Link>
290→                  ))}
291→                </div>
292→              </div>
293→            )}
294→          </nav>
295→
296→          {/* User section at bottom */}
297→          <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-border bg-background">
298→            <div className="flex items-center gap-3">
299→              <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
300→                <Icon icon="user" size="sm" className="text-primary" />
301→              </div>
302→              <div className="flex-1 min-w-0">
303→                <p className="text-sm font-medium text-foreground truncate">
304→                  {session.user?.name || 'User'}
305→                </p>
306→                <p className="text-xs text-foreground-tertiary truncate">{session.user?.email}</p>
307→              </div>
308→            </div>
309→          </div>
310→        </aside>
311→
312→        {/* Main content */}
313→        <main
314→          className={`flex-1 min-w-0 ${fullHeight ? 'flex flex-col h-[calc(100vh-64px)]' : ''}`}
315→        >
316→          {/* Content header */}
317→          <div
318→            className={`${fullHeight ? '' : 'sticky top-16'} z-10 bg-background border-b border-border`}
319→          >
320→            <div className="px-6 py-4">
321→              <div className="flex items-center justify-between">
322→                <div className="flex items-center gap-4">
323→                  {/* Mobile menu button */}
324→                  <Button
325→                    variant="ghost"
326→                    size="sm"
327→                    className="lg:hidden"
328→                    onClick={() => setSidebarOpen(true)}
329→                  >
330→                    <Icon icon="menu" size="sm" />
331→                  </Button>
332→
333→                  {/* Back button */}
334→                  {showBackButton && (
335→                    <Link
336→                      href={getBackUrl()}
337→                      className="text-foreground-secondary hover:text-foreground transition-colors"
338→                    >
339→                      <Icon icon="arrowLeft" size="sm" />
340→                    </Link>
341→                  )}
342→
343→                  {/* Title */}
344→                  <div>
345→                    <h1 className="text-xl font-semibold text-foreground">{title}</h1>
346→                    {subtitle && <p className="text-sm text-foreground-secondary">{subtitle}</p>}
347→                  </div>
348→                </div>
349→
350→                {/* Actions */}
351→                {actions && <div className="flex items-center gap-2">{actions}</div>}
352→              </div>
353→            </div>
354→          </div>
355→
356→          {/* Page content */}
357→          <div className={fullHeight ? 'flex-1 overflow-hidden' : 'p-6'}>{children}</div>
358→        </main>
359→      </div>
360→    </div>
361→  );
362→}
