  1→'use client';
  2→
  3→import type { AIProvider } from '@tpmjs/types/agent';
  4→import { Badge } from '@tpmjs/ui/Badge/Badge';
  5→import { Button } from '@tpmjs/ui/Button/Button';
  6→import { Icon } from '@tpmjs/ui/Icon/Icon';
  7→import {
  8→  Table,
  9→  TableBody,
 10→  TableCell,
 11→  TableEmpty,
 12→  TableHead,
 13→  TableHeader,
 14→  TableRow,
 15→} from '@tpmjs/ui/Table/Table';
 16→import Link from 'next/link';
 17→import { useRouter } from 'next/navigation';
 18→import { useCallback, useEffect, useState } from 'react';
 19→import { DashboardLayout } from '~/components/dashboard/DashboardLayout';
 20→
 21→interface Agent {
 22→  id: string;
 23→  uid: string;
 24→  name: string;
 25→  description: string | null;
 26→  provider: AIProvider;
 27→  modelId: string;
 28→  toolCount: number;
 29→  collectionCount: number;
 30→  createdAt: string;
 31→  updatedAt: string;
 32→}
 33→
 34→const PROVIDER_DISPLAY_NAMES: Record<AIProvider, string> = {
 35→  OPENAI: 'OpenAI',
 36→  ANTHROPIC: 'Anthropic',
 37→  GOOGLE: 'Google',
 38→  GROQ: 'Groq',
 39→  MISTRAL: 'Mistral',
 40→};
 41→
 42→const PROVIDER_COLORS: Record<AIProvider, 'default' | 'secondary' | 'outline'> = {
 43→  OPENAI: 'default',
 44→  ANTHROPIC: 'secondary',
 45→  GOOGLE: 'outline',
 46→  GROQ: 'outline',
 47→  MISTRAL: 'outline',
 48→};
 49→
 50→function formatDate(dateString: string): string {
 51→  const date = new Date(dateString);
 52→  return date.toLocaleDateString('en-US', {
 53→    month: 'short',
 54→    day: 'numeric',
 55→    year: 'numeric',
 56→  });
 57→}
 58→
 59→export default function AgentsPage(): React.ReactElement {
 60→  const router = useRouter();
 61→  const [agents, setAgents] = useState<Agent[]>([]);
 62→  const [isLoading, setIsLoading] = useState(true);
 63→  const [error, setError] = useState<string | null>(null);
 64→  const [deletingId, setDeletingId] = useState<string | null>(null);
 65→
 66→  const fetchAgents = useCallback(async () => {
 67→    try {
 68→      const response = await fetch('/api/agents');
 69→      const data = await response.json();
 70→
 71→      if (data.success) {
 72→        setAgents(data.data);
 73→      } else {
 74→        if (response.status === 401) {
 75→          router.push('/sign-in');
 76→          return;
 77→        }
 78→        setError(data.error || 'Failed to fetch agents');
 79→      }
 80→    } catch (err) {
 81→      console.error('Failed to fetch agents:', err);
 82→      setError('Failed to fetch agents');
 83→    } finally {
 84→      setIsLoading(false);
 85→    }
 86→  }, [router]);
 87→
 88→  useEffect(() => {
 89→    fetchAgents();
 90→  }, [fetchAgents]);
 91→
 92→  const handleDelete = async (id: string, e: React.MouseEvent) => {
 93→    e.stopPropagation();
 94→    if (!confirm('Are you sure you want to delete this agent? This action cannot be undone.')) {
 95→      return;
 96→    }
 97→
 98→    setDeletingId(id);
 99→    try {
100→      const response = await fetch(`/api/agents/${id}`, {
101→        method: 'DELETE',
102→      });
103→
104→      const result = await response.json();
105→
106→      if (result.success) {
107→        setAgents((prev) => prev.filter((a) => a.id !== id));
108→      } else {
109→        throw new Error(result.error || 'Failed to delete agent');
110→      }
111→    } catch (err) {
112→      console.error('Failed to delete agent:', err);
113→      alert(err instanceof Error ? err.message : 'Failed to delete agent');
114→    } finally {
115→      setDeletingId(null);
116→    }
117→  };
118→
119→  if (error) {
120→    return (
121→      <DashboardLayout
122→        title="Agents"
123→        actions={
124→          <Link href="/dashboard/agents/new">
125→            <Button>
126→              <Icon icon="plus" size="sm" className="mr-2" />
127→              New Agent
128→            </Button>
129→          </Link>
130→        }
131→      >
132→        <div className="text-center py-16">
133→          <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
134→          <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
135→          <p className="text-foreground-secondary mb-4">{error}</p>
136→          <Button onClick={fetchAgents}>Try Again</Button>
137→        </div>
138→      </DashboardLayout>
139→    );
140→  }
141→
142→  return (
143→    <DashboardLayout
144→      title="Agents"
145→      subtitle={
146→        agents.length > 0 ? `${agents.length} agent${agents.length !== 1 ? 's' : ''}` : undefined
147→      }
148→      actions={
149→        <Link href="/dashboard/agents/new">
150→          <Button>
151→            <Icon icon="plus" size="sm" className="mr-2" />
152→            New Agent
153→          </Button>
154→        </Link>
155→      }
156→    >
157→      <div className="bg-surface border border-border rounded-lg overflow-hidden">
158→        <Table>
159→          <TableHeader>
160→            <TableRow>
161→              <TableHead className="w-[300px]">Name</TableHead>
162→              <TableHead>Provider</TableHead>
163→              <TableHead>Tools</TableHead>
164→              <TableHead>Updated</TableHead>
165→              <TableHead className="w-[140px] text-right">Actions</TableHead>
166→            </TableRow>
167→          </TableHeader>
168→          <TableBody>
169→            {isLoading ? (
170→              // Loading skeleton
171→              [0, 1, 2].map((idx) => (
172→                <TableRow key={`agent-skeleton-${idx}`}>
173→                  <TableCell>
174→                    <div className="flex items-center gap-3">
175→                      <div className="w-8 h-8 rounded-lg bg-surface-secondary animate-pulse" />
176→                      <div className="space-y-1.5">
177→                        <div className="h-4 w-32 bg-surface-secondary rounded animate-pulse" />
178→                        <div className="h-3 w-48 bg-surface-secondary rounded animate-pulse" />
179→                      </div>
180→                    </div>
181→                  </TableCell>
182→                  <TableCell>
183→                    <div className="h-5 w-20 bg-surface-secondary rounded animate-pulse" />
184→                  </TableCell>
185→                  <TableCell>
186→                    <div className="h-4 w-12 bg-surface-secondary rounded animate-pulse" />
187→                  </TableCell>
188→                  <TableCell>
189→                    <div className="h-4 w-24 bg-surface-secondary rounded animate-pulse" />
190→                  </TableCell>
191→                  <TableCell>
192→                    <div className="h-8 w-24 bg-surface-secondary rounded animate-pulse ml-auto" />
193→                  </TableCell>
194→                </TableRow>
195→              ))
196→            ) : agents.length === 0 ? (
197→              <TableEmpty
198→                colSpan={5}
199→                icon={
200→                  <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
201→                    <Icon icon="terminal" size="lg" className="text-primary" />
202→                  </div>
203→                }
204→                title="No agents yet"
205→                description="Create your first AI agent to start chatting with tools. Agents can use any tools from your collections or individual tools."
206→                action={
207→                  <Link href="/dashboard/agents/new">
208→                    <Button>
209→                      <Icon icon="plus" size="sm" className="mr-2" />
210→                      Create Your First Agent
211→                    </Button>
212→                  </Link>
213→                }
214→              />
215→            ) : (
216→              agents.map((agent) => (
217→                <TableRow
218→                  key={agent.id}
219→                  interactive
220→                  onClick={() => router.push(`/dashboard/agents/${agent.id}`)}
221→                  className="cursor-pointer"
222→                >
223→                  <TableCell>
224→                    <div className="flex items-center gap-3">
225→                      <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
226→                        <Icon icon="terminal" size="sm" className="text-primary" />
227→                      </div>
228→                      <div className="min-w-0">
229→                        <p className="font-medium text-foreground truncate">{agent.name}</p>
230→                        {agent.description && (
231→                          <p className="text-sm text-foreground-tertiary truncate max-w-[250px]">
232→                            {agent.description}
233→                          </p>
234→                        )}
235→                      </div>
236→                    </div>
237→                  </TableCell>
238→                  <TableCell>
239→                    <div className="flex items-center gap-2">
240→                      <Badge variant={PROVIDER_COLORS[agent.provider]} size="sm">
241→                        {PROVIDER_DISPLAY_NAMES[agent.provider]}
242→                      </Badge>
243→                      <span className="text-xs text-foreground-tertiary">{agent.modelId}</span>
244→                    </div>
245→                  </TableCell>
246→                  <TableCell>
247→                    <span className="text-foreground-secondary">
248→                      {agent.toolCount > 0 && agent.collectionCount > 0
249→                        ? `${agent.toolCount} + ${agent.collectionCount} collections`
250→                        : agent.collectionCount > 0
251→                          ? `${agent.collectionCount} collection${agent.collectionCount !== 1 ? 's' : ''}`
252→                          : agent.toolCount}
253→                    </span>
254→                  </TableCell>
255→                  <TableCell>
256→                    <span className="text-foreground-secondary text-sm">
257→                      {formatDate(agent.updatedAt)}
258→                    </span>
259→                  </TableCell>
260→                  <TableCell>
261→                    <div className="flex items-center justify-end gap-1">
262→                      <Link
263→                        href={`/dashboard/agents/${agent.id}/chat`}
264→                        onClick={(e) => e.stopPropagation()}
265→                      >
266→                        <Button size="sm" variant="default">
267→                          <Icon icon="message" size="xs" className="mr-1" />
268→                          Chat
269→                        </Button>
270→                      </Link>
271→                      <Button
272→                        size="sm"
273→                        variant="ghost"
274→                        onClick={(e) => handleDelete(agent.id, e)}
275→                        disabled={deletingId === agent.id}
276→                      >
277→                        <Icon icon="trash" size="xs" />
278→                      </Button>
279→                    </div>
280→                  </TableCell>
281→                </TableRow>
282→              ))
283→            )}
284→          </TableBody>
285→        </Table>
286→      </div>
287→    </DashboardLayout>
