 11→/**
 12→ * Generate a URL-friendly UID from a name
 13→ */
 14→function generateUid(name: string): string {
 15→  return name
 16→    .toLowerCase()
 17→    .replace(/[^a-z0-9\s-]/g, '')
 18→    .replace(/\s+/g, '-')
 19→    .replace(/-+/g, '-')
 20→    .replace(/^-|-$/g, '')
 21→    .slice(0, 50);
 22→}
