 90→/**
 91→ * POST /api/agents
 92→ * Create a new agent
 93→ */
 94→export async function POST(request: NextRequest): Promise<NextResponse> {
 95→  try {
 96→    const authResult = await authenticateRequest();
 97→    if (!authResult.authenticated || !authResult.userId) {
 98→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 99→    }
100→    const userId = authResult.userId;
101→
102→    const body = await request.json();
103→    const parsed = CreateAgentSchema.safeParse(body);
104→    if (!parsed.success) {
105→      return NextResponse.json(
106→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
107→        { status: 400 }
108→      );
109→    }
110→
111→    // Check agent limit
112→    const agentCount = await prisma.agent.count({
113→      where: { userId },
114→    });
115→    if (agentCount >= AGENT_LIMITS.MAX_AGENTS_PER_USER) {
116→      return NextResponse.json(
117→        { success: false, error: `Maximum ${AGENT_LIMITS.MAX_AGENTS_PER_USER} agents allowed` },
118→        { status: 400 }
119→      );
120→    }
121→
122→    const {
123→      name,
124→      uid,
125→      description,
126→      provider,
127→      modelId,
128→      systemPrompt,
129→      temperature,
130→      maxToolCallsPerTurn,
131→      maxMessagesInContext,
132→      isPublic,
133→      collectionIds,
134→      toolIds,
135→    } = parsed.data;
136→
137→    // Generate UID if not provided
138→    let finalUid = uid || generateUid(name);
139→
140→    // Check for UID uniqueness
141→    const existingByUid = await prisma.agent.findUnique({ where: { uid: finalUid } });
142→    if (existingByUid) {
143→      // Append random suffix if UID exists
144→      finalUid = `${finalUid}-${Math.random().toString(36).slice(2, 6)}`;
145→    }
146→
147→    // Check for name uniqueness within user's agents
148→    const existingByName = await prisma.agent.findFirst({
149→      where: { userId, name },
150→    });
151→    if (existingByName) {
152→      return NextResponse.json(
153→        { success: false, error: 'An agent with this name already exists' },
154→        { status: 409 }
155→      );
156→    }
157→
158→    // Create agent with auto-like (user likes their own agent)
159→    const agent = await prisma.$transaction(async (tx) => {
160→      const newAgent = await tx.agent.create({
161→        data: {
162→          userId,
163→          uid: finalUid,
164→          name,
165→          description,
166→          provider,
167→          modelId,
168→          systemPrompt,
169→          temperature,
170→          maxToolCallsPerTurn,
171→          maxMessagesInContext,
172→          isPublic,
173→          likeCount: 1, // Start with 1 like (from owner)
174→          collections: collectionIds?.length
175→            ? {
176→                create: collectionIds.map((collectionId, index) => ({
177→                  collectionId,
178→                  position: index,
179→                })),
180→              }
181→            : undefined,
182→          tools: toolIds?.length
183→            ? {
184→                create: toolIds.map((toolId, index) => ({
185→                  toolId,
186→                  position: index,
187→                })),
188→              }
189→            : undefined,
190→        },
191→        select: {
192→          id: true,
193→          uid: true,
194→          name: true,
195→          description: true,
196→          provider: true,
197→          modelId: true,
198→          systemPrompt: true,
199→          temperature: true,
200→          maxToolCallsPerTurn: true,
201→          maxMessagesInContext: true,
202→          isPublic: true,
203→          createdAt: true,
204→          updatedAt: true,
205→          _count: {
206→            select: {
207→              tools: true,
208→              collections: true,
209→            },
210→          },
211→        },
212→      });
213→
214→      // Auto-like the agent
215→      await tx.agentLike.create({
216→        data: {
217→          userId,
218→          agentId: newAgent.id,
219→        },
220→      });
221→
222→      return newAgent;
223→    });
224→
225→    // Log activity (fire-and-forget)
226→    logActivity({
227→      userId,
228→      type: 'AGENT_CREATED',
229→      targetName: agent.name,
230→      targetType: 'agent',
231→      agentId: agent.id,
232→    });
233→
234→    return NextResponse.json(
235→      {
236→        success: true,
237→        data: {
238→          ...agent,
239→          toolCount: agent._count.tools,
240→          collectionCount: agent._count.collections,
241→          _count: undefined,
242→        },
243→      },
244→      { status: 201 }
245→    );
246→  } catch (error) {
247→    console.error('Failed to create agent:', error);
248→    return NextResponse.json({ success: false, error: 'Failed to create agent' }, { status: 500 });
249→  }
250→}
