  2→import { prisma } from '@tpmjs/db';
  3→import { headers } from 'next/headers';
  4→import { auth } from '~/lib/auth';
  5→import { type ApiKeyScope, hashApiKey, isValidApiKeyFormat } from './index';
  6→
  7→/**
  8→ * Result of authentication attempt
  9→ */
 10→export interface AuthResult {
 11→  /** Whether the request is authenticated */
 12→  authenticated: boolean;
 13→  /** User ID if authenticated */
 14→  userId?: string;
 15→  /** API key ID if authenticated via API key */
 16→  apiKeyId?: string;
 17→  /** Scopes available to this authentication */
 18→  scopes?: string[];
 19→  /** User's tier for rate limiting */
 20→  tier?: UserTier;
 21→  /** Error message if authentication failed */
 22→  error?: string;
 23→  /** Whether this is a session-based auth (vs API key) */
 24→  isSessionAuth?: boolean;
 25→}
 26→
 27→/**
 28→ * Authenticates a request using either session or API key
 29→ *
 30→ * Session auth is checked first (for dashboard users).
 31→ * If no session, API key auth is attempted.
 32→ *
 33→ * @returns AuthResult with authentication details
 34→ *
 35→ * @example
 36→ * const auth = await authenticateRequest();
 37→ * if (!auth.authenticated) {
 38→ *   return NextResponse.json({ error: auth.error }, { status: 401 });
 39→ * }
 40→ * // Use auth.userId, auth.apiKeyId, auth.scopes, auth.tier
 41→ */
 42→export async function authenticateRequest(): Promise<AuthResult> {
 43→  // 1. Try session auth first (for dashboard users)
 44→  try {
 45→    const session = await auth.api.getSession({ headers: await headers() });
 46→    if (session?.user?.id) {
 47→      const user = await prisma.user.findUnique({
 48→        where: { id: session.user.id },
 49→        select: { tier: true },
 50→      });
 51→      return {
 52→        authenticated: true,
 53→        userId: session.user.id,
 54→        tier: user?.tier || 'FREE',
 55→        scopes: ['*'], // Session users have full access to their own resources
 56→        isSessionAuth: true,
 57→      };
 58→    }
 59→  } catch {
 60→    // Session auth failed, try API key auth
 61→  }
 62→
 63→  // 2. Try API key auth
 64→  const headersList = await headers();
 65→  const authHeader = headersList.get('authorization');
 66→
 67→  if (!authHeader) {
 68→    return { authenticated: false, error: 'Missing authorization header' };
 69→  }
 70→
 71→  if (!authHeader.startsWith('Bearer ')) {
 72→    return {
 73→      authenticated: false,
 74→      error: 'Invalid authorization header format. Use: Bearer <api_key>',
 75→    };
 76→  }
 77→
 78→  const rawKey = authHeader.slice(7);
 79→
 80→  if (!rawKey) {
 81→    return { authenticated: false, error: 'API key is empty' };
 82→  }
 83→
 84→  if (!isValidApiKeyFormat(rawKey)) {
 85→    return {
 86→      authenticated: false,
 87→      error: 'Invalid API key format. Keys must start with tpmjs_sk_',
 88→    };
 89→  }
 90→
 91→  const keyHash = hashApiKey(rawKey);
 92→
 93→  const apiKey = await prisma.tpmjsApiKey.findUnique({
 94→    where: { keyHash },
 95→    include: { user: { select: { tier: true } } },
 96→  });
 97→
 98→  if (!apiKey) {
 99→    return { authenticated: false, error: 'Invalid API key' };
100→  }
101→
102→  if (!apiKey.isActive) {
103→    return { authenticated: false, error: 'API key is inactive' };
104→  }
105→
106→  if (apiKey.expiresAt && apiKey.expiresAt < new Date()) {
107→    return { authenticated: false, error: 'API key has expired' };
108→  }
109→
110→  // Update last used timestamp (fire and forget - non-blocking)
111→  prisma.tpmjsApiKey
112→    .update({
113→      where: { id: apiKey.id },
114→      data: { lastUsedAt: new Date() },
115→    })
116→    .catch(() => {
117→      // Ignore errors - this is just for tracking
118→    });
119→
120→  return {
121→    authenticated: true,
122→    userId: apiKey.userId,
123→    apiKeyId: apiKey.id,
124→    scopes: apiKey.scopes,
125→    tier: apiKey.user.tier,
126→    isSessionAuth: false,
127→  };
128→}
129→
130→/**
131→ * Checks if an auth result has a required scope
132→ *
133→ * Session auth always has all scopes ('*').
134→ * API key auth checks the specific scopes granted.
135→ *
136→ * @param authResult - The authentication result
137→ * @param requiredScope - The scope to check
138→ * @returns True if the auth has the required scope
139→ *
140→ * @example
141→ * const auth = await authenticateRequest();
142→ * if (!hasScope(auth, 'mcp:execute')) {
143→ *   return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 });
144→ * }
145→ */
146→export function hasScope(authResult: AuthResult, requiredScope: ApiKeyScope): boolean {
147→  if (!authResult.authenticated || !authResult.scopes) {
148→    return false;
149→  }
150→
151→  // Session auth has full access
152→  if (authResult.scopes.includes('*')) {
153→    return true;
154→  }
155→
156→  return authResult.scopes.includes(requiredScope);
157→}
158→
159→/**
160→ * Requires authentication and optionally a specific scope
161→ *
162→ * This is a convenience wrapper that returns an error response if auth fails.
163→ *
164→ * @param requiredScope - Optional scope to require
165→ * @returns AuthResult if authenticated, or null with error details
166→ *
167→ * @example
168→ * const { auth, errorResponse } = await requireAuth('mcp:execute');
169→ * if (errorResponse) return errorResponse;
170→ * // auth is guaranteed to be valid here
171→ */
172→export async function requireAuth(
173→  requiredScope?: ApiKeyScope
174→): Promise<{ auth: AuthResult | null; errorResponse: Response | null }> {
175→  const authResult = await authenticateRequest();
176→
177→  if (!authResult.authenticated) {
178→    return {
179→      auth: null,
180→      errorResponse: new Response(JSON.stringify({ error: authResult.error }), {
181→        status: 401,
182→        headers: { 'Content-Type': 'application/json' },
183→      }),
184→    };
185→  }
186→
187→  if (requiredScope && !hasScope(authResult, requiredScope)) {
188→    return {
189→      auth: null,
190→      errorResponse: new Response(
191→        JSON.stringify({
192→          error: `Missing required scope: ${requiredScope}`,
193→          requiredScope,
194→          availableScopes: authResult.scopes,
195→        }),
196→        {
197→          status: 403,
198→          headers: { 'Content-Type': 'application/json' },
199→        }
200→      ),
201→    };
202→  }
203→
204→  return { auth: authResult, errorResponse: null };
205→}
