 59→export default function AgentsPage(): React.ReactElement {
 60→  const router = useRouter();
 61→  const [agents, setAgents] = useState<Agent[]>([]);
 62→  const [isLoading, setIsLoading] = useState(true);
 63→  const [error, setError] = useState<string | null>(null);
 64→  const [deletingId, setDeletingId] = useState<string | null>(null);
 65→
 66→  const fetchAgents = useCallback(async () => {
 67→    try {
 68→      const response = await fetch('/api/agents');
 69→      const data = await response.json();
 70→
 71→      if (data.success) {
 72→        setAgents(data.data);
 73→      } else {
 74→        if (response.status === 401) {
 75→          router.push('/sign-in');
 76→          return;
 77→        }
 78→        setError(data.error || 'Failed to fetch agents');
 79→      }
 80→    } catch (err) {
 81→      console.error('Failed to fetch agents:', err);
 82→      setError('Failed to fetch agents');
 83→    } finally {
 84→      setIsLoading(false);
 85→    }
 86→  }, [router]);
 87→
 88→  useEffect(() => {
 89→    fetchAgents();
 90→  }, [fetchAgents]);
 91→
 92→  const handleDelete = async (id: string, e: React.MouseEvent) => {
 93→    e.stopPropagation();
 94→    if (!confirm('Are you sure you want to delete this agent? This action cannot be undone.')) {
 95→      return;
 96→    }
 97→
 98→    setDeletingId(id);
 99→    try {
100→      const response = await fetch(`/api/agents/${id}`, {
101→        method: 'DELETE',
102→      });
103→
104→      const result = await response.json();
105→
106→      if (result.success) {
107→        setAgents((prev) => prev.filter((a) => a.id !== id));
108→      } else {
109→        throw new Error(result.error || 'Failed to delete agent');
110→      }
111→    } catch (err) {
112→      console.error('Failed to delete agent:', err);
113→      alert(err instanceof Error ? err.message : 'Failed to delete agent');
114→    } finally {
115→      setDeletingId(null);
116→    }
117→  };
118→
119→  if (error) {
