172→                <TableRow key={`agent-skeleton-${idx}`}>
173→                  <TableCell>
174→                    <div className="flex items-center gap-3">
175→                      <div className="w-8 h-8 rounded-lg bg-surface-secondary animate-pulse" />
176→                      <div className="space-y-1.5">
177→                        <div className="h-4 w-32 bg-surface-secondary rounded animate-pulse" />
178→                        <div className="h-3 w-48 bg-surface-secondary rounded animate-pulse" />
179→                      </div>
180→                    </div>
181→                  </TableCell>
182→                  <TableCell>
183→                    <div className="h-5 w-20 bg-surface-secondary rounded animate-pulse" />
184→                  </TableCell>
185→                  <TableCell>
186→                    <div className="h-4 w-12 bg-surface-secondary rounded animate-pulse" />
187→                  </TableCell>
