  1→import { prisma } from '@tpmjs/db';
  2→import { AGENT_LIMITS, CreateAgentSchema } from '@tpmjs/types/agent';
  3→import { type NextRequest, NextResponse } from 'next/server';
  4→
  5→import { logActivity } from '~/lib/activity';
  6→import { authenticateRequest } from '~/lib/api-keys/middleware';
  7→
  8→export const runtime = 'nodejs';
  9→export const dynamic = 'force-dynamic';
 10→
 11→/**
 12→ * Generate a URL-friendly UID from a name
 13→ */
 14→function generateUid(name: string): string {
 15→  return name
 16→    .toLowerCase()
 17→    .replace(/[^a-z0-9\s-]/g, '')
 18→    .replace(/\s+/g, '-')
 19→    .replace(/-+/g, '-')
 20→    .replace(/^-|-$/g, '')
 21→    .slice(0, 50);
 22→}
 23→
 24→/**
 25→ * GET /api/agents
 26→ * List all agents owned by the authenticated user
 27→ */
 28→export async function GET(request: NextRequest): Promise<NextResponse> {
 29→  try {
 30→    const authResult = await authenticateRequest();
 31→    if (!authResult.authenticated || !authResult.userId) {
 32→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 33→    }
 34→
 35→    const { searchParams } = new URL(request.url);
 36→    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '20', 10), 50);
 37→    const offset = Number.parseInt(searchParams.get('offset') || '0', 10);
 38→
 39→    const agents = await prisma.agent.findMany({
 40→      where: { userId: authResult.userId },
 41→      select: {
 42→        id: true,
 43→        uid: true,
 44→        name: true,
 45→        description: true,
 46→        provider: true,
 47→        modelId: true,
 48→        temperature: true,
 49→        maxToolCallsPerTurn: true,
 50→        maxMessagesInContext: true,
 51→        isPublic: true,
 52→        createdAt: true,
 53→        updatedAt: true,
 54→        _count: {
 55→          select: {
 56→            tools: true,
 57→            collections: true,
 58→          },
 59→        },
 60→      },
 61→      orderBy: { updatedAt: 'desc' },
 62→      take: limit + 1,
 63→      skip: offset,
 64→    });
 65→
 66→    const hasMore = agents.length > limit;
 67→    const data = hasMore ? agents.slice(0, limit) : agents;
 68→
 69→    return NextResponse.json({
 70→      success: true,
 71→      data: data.map((a) => ({
 72→        ...a,
 73→        toolCount: a._count.tools,
 74→        collectionCount: a._count.collections,
 75→        _count: undefined,
 76→      })),
 77→      pagination: {
 78→        limit,
 79→        offset,
 80→        count: data.length,
 81→        hasMore,
 82→      },
 83→    });
 84→  } catch (error) {
 85→    console.error('Failed to list agents:', error);
 86→    return NextResponse.json({ success: false, error: 'Failed to list agents' }, { status: 500 });
 87→  }
 88→}
 89→
 90→/**
 91→ * POST /api/agents
 92→ * Create a new agent
 93→ */
 94→export async function POST(request: NextRequest): Promise<NextResponse> {
 95→  try {
 96→    const authResult = await authenticateRequest();
 97→    if (!authResult.authenticated || !authResult.userId) {
 98→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 99→    }
100→    const userId = authResult.userId;
101→
102→    const body = await request.json();
103→    const parsed = CreateAgentSchema.safeParse(body);
104→    if (!parsed.success) {
105→      return NextResponse.json(
106→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
107→        { status: 400 }
108→      );
109→    }
110→
111→    // Check agent limit
112→    const agentCount = await prisma.agent.count({
113→      where: { userId },
114→    });
115→    if (agentCount >= AGENT_LIMITS.MAX_AGENTS_PER_USER) {
116→      return NextResponse.json(
117→        { success: false, error: `Maximum ${AGENT_LIMITS.MAX_AGENTS_PER_USER} agents allowed` },
118→        { status: 400 }
119→      );
120→    }
121→
122→    const {
123→      name,
124→      uid,
125→      description,
126→      provider,
127→      modelId,
128→      systemPrompt,
129→      temperature,
130→      maxToolCallsPerTurn,
131→      maxMessagesInContext,
132→      isPublic,
133→      collectionIds,
134→      toolIds,
135→    } = parsed.data;
136→
137→    // Generate UID if not provided
138→    let finalUid = uid || generateUid(name);
139→
140→    // Check for UID uniqueness
141→    const existingByUid = await prisma.agent.findUnique({ where: { uid: finalUid } });
142→    if (existingByUid) {
143→      // Append random suffix if UID exists
144→      finalUid = `${finalUid}-${Math.random().toString(36).slice(2, 6)}`;
145→    }
146→
147→    // Check for name uniqueness within user's agents
148→    const existingByName = await prisma.agent.findFirst({
149→      where: { userId, name },
150→    });
151→    if (existingByName) {
152→      return NextResponse.json(
153→        { success: false, error: 'An agent with this name already exists' },
154→        { status: 409 }
155→      );
156→    }
157→
158→    // Create agent with auto-like (user likes their own agent)
159→    const agent = await prisma.$transaction(async (tx) => {
160→      const newAgent = await tx.agent.create({
161→        data: {
162→          userId,
163→          uid: finalUid,
164→          name,
165→          description,
166→          provider,
167→          modelId,
168→          systemPrompt,
169→          temperature,
170→          maxToolCallsPerTurn,
171→          maxMessagesInContext,
172→          isPublic,
173→          likeCount: 1, // Start with 1 like (from owner)
174→          collections: collectionIds?.length
175→            ? {
176→                create: collectionIds.map((collectionId, index) => ({
177→                  collectionId,
178→                  position: index,
179→                })),
180→              }
181→            : undefined,
182→          tools: toolIds?.length
183→            ? {
184→                create: toolIds.map((toolId, index) => ({
185→                  toolId,
186→                  position: index,
187→                })),
188→              }
189→            : undefined,
190→        },
191→        select: {
192→          id: true,
193→          uid: true,
194→          name: true,
195→          description: true,
196→          provider: true,
197→          modelId: true,
198→          systemPrompt: true,
199→          temperature: true,
200→          maxToolCallsPerTurn: true,
201→          maxMessagesInContext: true,
202→          isPublic: true,
203→          createdAt: true,
204→          updatedAt: true,
205→          _count: {
206→            select: {
207→              tools: true,
208→              collections: true,
209→            },
210→          },
211→        },
212→      });
213→
214→      // Auto-like the agent
215→      await tx.agentLike.create({
216→        data: {
217→          userId,
218→          agentId: newAgent.id,
219→        },
220→      });
221→
222→      return newAgent;
223→    });
224→
225→    // Log activity (fire-and-forget)
226→    logActivity({
227→      userId,
228→      type: 'AGENT_CREATED',
229→      targetName: agent.name,
230→      targetType: 'agent',
231→      agentId: agent.id,
232→    });
233→
234→    return NextResponse.json(
235→      {
236→        success: true,
237→        data: {
238→          ...agent,
239→          toolCount: agent._count.tools,
240→          collectionCount: agent._count.collections,
241→          _count: undefined,
242→        },
243→      },
244→      { status: 201 }
245→    );
246→  } catch (error) {
247→    console.error('Failed to create agent:', error);
248→    return NextResponse.json({ success: false, error: 'Failed to create agent' }, { status: 500 });
249→  }
250→}
