'use client';

import { Button } from '@tpmjs/ui/Button/Button';
import { Icon, type IconName } from '@tpmjs/ui/Icon/Icon';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import { useSession } from '@/lib/auth-client';
import { AppHeader } from '../AppHeader';

interface NavItem {
  href: string;
  label: string;
  icon: IconName;
  badge?: number;
}

interface NavSection {
  title?: string;
  items: NavItem[];
}

const navSections: NavSection[] = [
  {
    items: [
      { href: '/dashboard', label: 'Overview', icon: 'home' },
      { href: '/dashboard/activity', label: 'Activity', icon: 'barChart' },
      { href: '/dashboard/agents', label: 'Agents', icon: 'terminal' },
      { href: '/dashboard/collections', label: 'Collections', icon: 'folder' },
      { href: '/dashboard/memories', label: 'Memories', icon: 'database' },
    ],
  },
  {
    title: 'Settings',
    items: [
      { href: '/dashboard/settings/profile', label: 'Profile', icon: 'user' },
      { href: '/dashboard/settings/api-keys', label: 'AI Provider Keys', icon: 'puzzle' },
      { href: '/dashboard/settings/tpmjs-api-keys', label: 'Platform API Keys', icon: 'key' },
      { href: '/dashboard/settings/bridge', label: 'Bridge', icon: 'link' },
      { href: '/dashboard/usage', label: 'Usage', icon: 'globe' },
    ],
  },
];

const adminNavItems: NavItem[] = [
  { href: '/dashboard/admin', label: 'Overview', icon: 'barChart' },
  { href: '/dashboard/admin/users', label: 'Users', icon: 'user' },
];

const likesNavItems: NavItem[] = [
  { href: '/dashboard/likes/tools', label: 'Tools', icon: 'puzzle' },
  { href: '/dashboard/likes/collections', label: 'Collections', icon: 'folder' },
  { href: '/dashboard/likes/agents', label: 'Agents', icon: 'terminal' },
];

interface DashboardLayoutProps {
  children: React.ReactNode;
  /** Title displayed in the header */
  title: string;
  /** Optional subtitle/description */
  subtitle?: string;
  /** Action buttons for the header */
  actions?: React.ReactNode;
  /** Whether to show back button */
  showBackButton?: boolean;
  /** Custom back URL (defaults to parent route) */
  backUrl?: string;
  /** Whether to use full height layout (for chat interfaces) - removes padding and fills viewport */
  fullHeight?: boolean;
}

export function DashboardLayout({
  children,
  title,
  subtitle,
  actions,
  showBackButton,
  backUrl,
  fullHeight,
}: DashboardLayoutProps): React.ReactElement {
  const pathname = usePathname();
  const router = useRouter();
  const { data: session, isPending } = useSession();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isAdminUser, setIsAdminUser] = useState(false);
  const [likesExpanded, setLikesExpanded] = useState(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('dashboard-likes-expanded');
      return stored === 'true';
    }
    return false;
  });

  // Persist likes expanded state
  useEffect(() => {
    localStorage.setItem('dashboard-likes-expanded', String(likesExpanded));
  }, [likesExpanded]);

  // Auto-expand if on a likes page - intentional route-based UI sync
  useEffect(() => {
    if (pathname.startsWith('/dashboard/likes')) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setLikesExpanded(true);
    }
  }, [pathname]);

  // Redirect to sign-in if not authenticated
  useEffect(() => {
    if (!isPending && !session) {
      router.push('/sign-in');
    }
  }, [isPending, session, router]);

  // Check admin status
  useEffect(() => {
    if (session?.user?.id) {
      fetch('/api/admin/stats', { method: 'GET' })
        .then((res) => setIsAdminUser(res.ok))
        .catch(() => setIsAdminUser(false));
    }
  }, [session?.user?.id]);

  // Close sidebar on route change - intentional route-based UI sync
  // biome-ignore lint/correctness/useExhaustiveDependencies: pathname triggers effect
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setSidebarOpen(false);
  }, [pathname]);

  const isActive = (href: string) => {
    if (href === '/dashboard') {
      return pathname === '/dashboard';
    }
    return pathname.startsWith(href);
  };

  const isLikesActive = pathname.startsWith('/dashboard/likes');

  const getBackUrl = () => {
    if (backUrl) return backUrl;
    // Get parent route
    const parts = pathname.split('/').filter(Boolean);
    parts.pop();
    return parts.length > 0 ? `/${parts.join('/')}` : '/dashboard';
  };

  if (isPending) {
    return (
      <div className="min-h-screen bg-background">
        <AppHeader />
        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
          <div className="animate-pulse text-foreground-secondary">Loading...</div>
        </div>
      </div>
    );
  }

  if (!session) {
    return <div />;
  }

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />

      <div className="flex">
        {/* Mobile sidebar backdrop */}
        {sidebarOpen && (
          <button
            type="button"
            className="fixed inset-0 bg-black/50 z-40 lg:hidden cursor-default"
            onClick={() => setSidebarOpen(false)}
            aria-label="Close sidebar"
          />
        )}

        {/* Sidebar */}
        <aside
          className={`
            fixed lg:sticky top-16 left-0 z-50 lg:z-0
            w-64 h-[calc(100vh-64px)] bg-background border-r border-border
            transform transition-transform lg:transform-none
            ${sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
          `}
        >
          <nav className="p-4 space-y-6 overflow-y-auto h-[calc(100%-80px)]">
            {navSections.map((section, sectionIdx) => (
              <div key={section.title || `section-${sectionIdx}`}>
                {section.title && (
                  <h3 className="px-3 mb-2 text-xs font-semibold text-foreground-tertiary uppercase tracking-wider">
                    {section.title}
                  </h3>
                )}
                <div className="space-y-1">
                  {section.items.map((item) => (
                    <Link
                      key={item.href}
                      href={item.href}
                      className={`
                        flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors
                        ${
                          isActive(item.href)
                            ? 'bg-primary/10 text-primary'
                            : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
                        }
                      `}
                    >
                      <Icon icon={item.icon} size="sm" />
                      <span>{item.label}</span>
                      {item.badge !== undefined && item.badge > 0 && (
                        <span className="ml-auto text-xs bg-surface-secondary px-1.5 py-0.5 rounded-full">
                          {item.badge}
                        </span>
                      )}
                    </Link>
                  ))}
                </div>
              </div>
            ))}

            {/* Likes Section - Collapsible */}
            <div>
              <button
                type="button"
                onClick={() => setLikesExpanded(!likesExpanded)}
                className={`
                  w-full flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors
                  ${
                    isLikesActive
                      ? 'bg-primary/10 text-primary'
                      : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
                  }
                `}
              >
                <Icon icon="heart" size="sm" />
                <span>Likes</span>
                <Icon
                  icon={likesExpanded ? 'chevronDown' : 'chevronRight'}
                  size="xs"
                  className="ml-auto"
                />
              </button>

              {likesExpanded && (
                <div className="ml-4 mt-1 space-y-1">
                  {likesNavItems.map((item) => (
                    <Link
                      key={item.href}
                      href={item.href}
                      className={`
                        flex items-center gap-3 px-3 py-1.5 rounded-lg text-sm transition-colors
                        ${
                          isActive(item.href)
                            ? 'bg-primary/10 text-primary font-medium'
                            : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
                        }
                      `}
                    >
                      <Icon icon={item.icon} size="xs" />
                      <span>{item.label}</span>
                    </Link>
                  ))}
                </div>
              )}
            </div>

            {/* Admin Section - only shown for admin users */}
            {isAdminUser && (
              <div>
                <h3 className="px-3 mb-2 text-xs font-semibold text-foreground-tertiary uppercase tracking-wider">
                  Admin
                </h3>
                <div className="space-y-1">
                  {adminNavItems.map((item) => (
                    <Link
                      key={item.href}
                      href={item.href}
                      className={`
                        flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors
                        ${
                          isActive(item.href)
                            ? 'bg-primary/10 text-primary'
                            : 'text-foreground-secondary hover:text-foreground hover:bg-surface'
                        }
                      `}
                    >
                      <Icon icon={item.icon} size="sm" />
                      <span>{item.label}</span>
                    </Link>
                  ))}
                </div>
              </div>
            )}
          </nav>

          {/* User section at bottom */}
          <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-border bg-background">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center">
                <Icon icon="user" size="sm" className="text-primary" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-foreground truncate">
                  {session.user?.name || 'User'}
                </p>
                <p className="text-xs text-foreground-tertiary truncate">{session.user?.email}</p>
              </div>
            </div>
          </div>
        </aside>

        {/* Main content */}
        <main
          className={`flex-1 min-w-0 ${fullHeight ? 'flex flex-col h-[calc(100vh-64px)]' : ''}`}
        >
          {/* Content header */}
          <div
            className={`${fullHeight ? '' : 'sticky top-16'} z-10 bg-background border-b border-border`}
          >
            <div className="px-6 py-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                  {/* Mobile menu button */}
                  <Button
                    variant="ghost"
                    size="sm"
                    className="lg:hidden"
                    onClick={() => setSidebarOpen(true)}
                  >
                    <Icon icon="menu" size="sm" />
                  </Button>

                  {/* Back button */}
                  {showBackButton && (
                    <Link
                      href={getBackUrl()}
                      className="text-foreground-secondary hover:text-foreground transition-colors"
                    >
                      <Icon icon="arrowLeft" size="sm" />
                    </Link>
                  )}

                  {/* Title */}
                  <div>
                    <h1 className="text-xl font-semibold text-foreground">{title}</h1>
                    {subtitle && <p className="text-sm text-foreground-secondary">{subtitle}</p>}
                  </div>
                </div>

                {/* Actions */}
                {actions && <div className="flex items-center gap-2">{actions}</div>}
              </div>
            </div>
          </div>

          {/* Page content */}
          <div className={fullHeight ? 'flex-1 overflow-hidden' : 'p-6'}>{children}</div>
        </main>
      </div>
    </div>
  );
}

