import { prisma } from '@tpmjs/db';
import { AGENT_LIMITS, CreateAgentSchema } from '@tpmjs/types/agent';
import { type NextRequest, NextResponse } from 'next/server';

import { logActivity } from '~/lib/activity';
import { authenticateRequest } from '~/lib/api-keys/middleware';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

/**
 * Generate a URL-friendly UID from a name
 */
function generateUid(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 50);
}

/**
 * GET /api/agents
 * List all agents owned by the authenticated user
 */
export async function GET(request: NextRequest): Promise<NextResponse> {
  try {
    const authResult = await authenticateRequest();
    if (!authResult.authenticated || !authResult.userId) {
      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '20', 10), 50);
    const offset = Number.parseInt(searchParams.get('offset') || '0', 10);

    const agents = await prisma.agent.findMany({
      where: { userId: authResult.userId },
      select: {
        id: true,
        uid: true,
        name: true,
        description: true,
        provider: true,
        modelId: true,
        temperature: true,
        maxToolCallsPerTurn: true,
        maxMessagesInContext: true,
        isPublic: true,
        createdAt: true,
        updatedAt: true,
        _count: {
          select: {
            tools: true,
            collections: true,
          },
        },
      },
      orderBy: { updatedAt: 'desc' },
      take: limit + 1,
      skip: offset,
    });

    const hasMore = agents.length > limit;
    const data = hasMore ? agents.slice(0, limit) : agents;

    return NextResponse.json({
      success: true,
      data: data.map((a) => ({
        ...a,
        toolCount: a._count.tools,
        collectionCount: a._count.collections,
        _count: undefined,
      })),
      pagination: {
        limit,
        offset,
        count: data.length,
        hasMore,
      },
    });
  } catch (error) {
    console.error('Failed to list agents:', error);
    return NextResponse.json({ success: false, error: 'Failed to list agents' }, { status: 500 });
  }
}

/**
 * POST /api/agents
 * Create a new agent
 */
export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const authResult = await authenticateRequest();
    if (!authResult.authenticated || !authResult.userId) {
      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    }
    const userId = authResult.userId;

    const body = await request.json();
    const parsed = CreateAgentSchema.safeParse(body);
    if (!parsed.success) {
      return NextResponse.json(
        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    // Check agent limit
    const agentCount = await prisma.agent.count({
      where: { userId },
    });
    if (agentCount >= AGENT_LIMITS.MAX_AGENTS_PER_USER) {
      return NextResponse.json(
        { success: false, error: `Maximum ${AGENT_LIMITS.MAX_AGENTS_PER_USER} agents allowed` },
        { status: 400 }
      );
    }

    const {
      name,
      uid,
      description,
      provider,
      modelId,
      systemPrompt,
      temperature,
      maxToolCallsPerTurn,
      maxMessagesInContext,
      isPublic,
      collectionIds,
      toolIds,
    } = parsed.data;

    // Generate UID if not provided
    let finalUid = uid || generateUid(name);

    // Check for UID uniqueness
    const existingByUid = await prisma.agent.findUnique({ where: { uid: finalUid } });
    if (existingByUid) {
      // Append random suffix if UID exists
      finalUid = `${finalUid}-${Math.random().toString(36).slice(2, 6)}`;
    }

    // Check for name uniqueness within user's agents
    const existingByName = await prisma.agent.findFirst({
      where: { userId, name },
    });
    if (existingByName) {
      return NextResponse.json(
        { success: false, error: 'An agent with this name already exists' },
        { status: 409 }
      );
    }

    // Create agent with auto-like (user likes their own agent)
    const agent = await prisma.$transaction(async (tx) => {
      const newAgent = await tx.agent.create({
        data: {
          userId,
          uid: finalUid,
          name,
          description,
          provider,
          modelId,
          systemPrompt,
          temperature,
          maxToolCallsPerTurn,
          maxMessagesInContext,
          isPublic,
          likeCount: 1, // Start with 1 like (from owner)
          collections: collectionIds?.length
            ? {
                create: collectionIds.map((collectionId, index) => ({
                  collectionId,
                  position: index,
                })),
              }
            : undefined,
          tools: toolIds?.length
            ? {
                create: toolIds.map((toolId, index) => ({
                  toolId,
                  position: index,
                })),
              }
            : undefined,
        },
        select: {
          id: true,
          uid: true,
          name: true,
          description: true,
          provider: true,
          modelId: true,
          systemPrompt: true,
          temperature: true,
          maxToolCallsPerTurn: true,
          maxMessagesInContext: true,
          isPublic: true,
          createdAt: true,
          updatedAt: true,
          _count: {
            select: {
              tools: true,
              collections: true,
            },
          },
        },
      });

      // Auto-like the agent
      await tx.agentLike.create({
        data: {
          userId,
          agentId: newAgent.id,
        },
      });

      return newAgent;
    });

    // Log activity (fire-and-forget)
    logActivity({
      userId,
      type: 'AGENT_CREATED',
      targetName: agent.name,
      targetType: 'agent',
      agentId: agent.id,
    });

    return NextResponse.json(
      {
        success: true,
        data: {
          ...agent,
          toolCount: agent._count.tools,
          collectionCount: agent._count.collections,
          _count: undefined,
        },
      },
      { status: 201 }
    );
  } catch (error) {
    console.error('Failed to create agent:', error);
    return NextResponse.json({ success: false, error: 'Failed to create agent' }, { status: 500 });
  }
}

// This is your Prisma schema file,
// learn more about it in the docs: https://pris.ly/d/prisma-schema

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider  = "postgresql"
  url       = env("DATABASE_URL")
  directUrl = env("DATABASE_URL_UNPOOLED") // Direct connection for migrations (bypasses pooler)
}

/// Package table - stores NPM package metadata (package-level)
model Package {
  id String @id @default(cuid())

  // NPM Metadata
  npmPackageName String   @unique @map("npm_package_name") @db.VarChar(214)
  npmVersion     String   @map("npm_version") @db.VarChar(50)
  npmPublishedAt DateTime @map("npm_published_at")
  npmDescription String?  @map("npm_description") @db.Text
  npmRepository  Json?    @map("npm_repository") @db.JsonB
  npmHomepage    String?  @map("npm_homepage") @db.Text
  npmLicense     String?  @map("npm_license") @db.VarChar(50)
  npmKeywords    String[] @default([]) @map("npm_keywords") @db.Text
  npmReadme      String?  @map("npm_readme") @db.Text
  npmAuthor      Json?    @map("npm_author") @db.JsonB
  npmMaintainers Json?    @map("npm_maintainers") @db.JsonB

  // TPMJS Package-Level Metadata
  category       String   @db.VarChar(50)
  env            Json?    @db.JsonB // Environment variables (shared across tools)
  frameworks     String[] @default([]) @db.Text
  tier           String   @db.VarChar(20) // 'minimal' | 'rich'
  discoveryMethod String  @map("discovery_method") @db.VarChar(20) // 'keyword' | 'changes-feed'
  isOfficial     Boolean  @default(false) @map("is_official")

  // Package Metrics
  npmDownloadsLastMonth Int? @default(0) @map("npm_downloads_last_month")
  githubStars           Int? @default(0) @map("github_stars")

  // Timestamps
  createdAt DateTime @default(now()) @map("created_at")
  updatedAt DateTime @updatedAt @map("updated_at")

  // Relations
  tools Tool[]

  @@index([category])
  @@index([isOfficial])
  @@index([npmDownloadsLastMonth])
  @@index([createdAt])
  @@map("packages")
}

/// Tool table - stores individual tools within packages
model Tool {
  id String @id @default(cuid())

  // Package Relation
  packageId String  @map("package_id")
  package   Package @relation(fields: [packageId], references: [id], onDelete: Cascade)

  // Tool Identity
  name String @db.VarChar(100) // e.g., "helloWorldTool", "default"

  // Tool Metadata
  description String @db.Text
  parameters  Json?  @db.JsonB // Legacy/fallback - author-provided parameters array
  returns     Json?  @db.JsonB // @deprecated - will be auto-extracted in future
  aiAgent     Json?  @map("ai_agent") @db.JsonB // @deprecated - will be auto-extracted in future

  // Schema Extraction Fields
  inputSchema                Json?     @map("input_schema") @db.JsonB // Full JSON Schema from executor
  schemaSource               String?   @map("schema_source") @db.VarChar(20) // 'extracted' | 'author' | null
  schemaExtractedAt          DateTime? @map("schema_extracted_at") // Only updated on successful extraction
  schemaExtractionAttemptAt  DateTime? @map("schema_extraction_attempt_at") // Updated on every attempt (for rate limiting)
  schemaExtractionError      String?   @map("schema_extraction_error") @db.Text // Error message from last failed attempt

  // Tool Discovery Fields
  toolDiscoverySource String? @map("tool_discovery_source") @db.VarChar(20) // 'auto' | 'manual' | null

  // Tool Metrics
  qualityScore Decimal? @map("quality_score") @db.Decimal(3, 2) // 0.00 to 1.00
  likeCount    Int      @default(0) @map("like_count")

  // Health Status Fields
  importHealth     HealthStatus? @default(UNKNOWN) @map("import_health")
  executionHealth  HealthStatus? @default(UNKNOWN) @map("execution_health")
  lastHealthCheck  DateTime?     @map("last_health_check")
  healthCheckError String?       @map("health_check_error") @db.Text

  // Timestamps
  createdAt DateTime @default(now()) @map("created_at")
  updatedAt DateTime @updatedAt @map("updated_at")

  // View tracking (denormalized, rolled up daily)
  viewCount      Int      @default(0) @map("view_count")

