'use client';

import type { AIProvider } from '@tpmjs/types/agent';
import { PROVIDER_MODELS, SUPPORTED_PROVIDERS } from '@tpmjs/types/agent';
import { Button } from '@tpmjs/ui/Button/Button';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Input } from '@tpmjs/ui/Input/Input';
import { Label } from '@tpmjs/ui/Label/Label';
import { Select } from '@tpmjs/ui/Select/Select';
import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { AppHeader } from '~/components/AppHeader';

const PROVIDER_DISPLAY_NAMES: Record<AIProvider, string> = {
  OPENAI: 'OpenAI',
  ANTHROPIC: 'Anthropic',
  GOOGLE: 'Google',
  GROQ: 'Groq',
  MISTRAL: 'Mistral',
};

interface FormData {
  name: string;
  uid: string;
  description: string;
  provider: AIProvider;
  modelId: string;
  systemPrompt: string;
  temperature: number;
  maxToolCallsPerTurn: number;
  maxMessagesInContext: number;
}

export default function NewAgentPage(): React.ReactElement {
  const router = useRouter();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<FormData>({
    name: '',
    uid: '',
    description: '',
    provider: 'OPENAI',
    modelId: 'gpt-4.1-mini',
    systemPrompt: '',
    temperature: 0.7,
    maxToolCallsPerTurn: 20,
    maxMessagesInContext: 10,
  });

  const handleChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    setFormData((prev) => {
      const newData = { ...prev, [name]: value };

      // Auto-generate uid from name if uid is empty or was auto-generated
      if (name === 'name' && (!prev.uid || prev.uid === generateUid(prev.name))) {
        newData.uid = generateUid(value);
      }

      // Reset model when provider changes
      if (name === 'provider') {
        const provider = value as AIProvider;
        const models = PROVIDER_MODELS[provider];
        newData.modelId = models?.[0]?.id || '';
      }

      return newData;
    });
  };

  const generateUid = (name: string): string => {
    return name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 50);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsSubmitting(true);

    try {
      const response = await fetch('/api/agents', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...formData,
          temperature: Number.parseFloat(formData.temperature.toString()),
          maxToolCallsPerTurn: Number.parseInt(formData.maxToolCallsPerTurn.toString(), 10),
          maxMessagesInContext: Number.parseInt(formData.maxMessagesInContext.toString(), 10),
        }),
      });

      const result = await response.json();

      if (result.success) {
        router.push(`/dashboard/agents/${result.data.id}`);
      } else {
        throw new Error(result.error || 'Failed to create agent');
      }
    } catch (err) {
      console.error('Failed to create agent:', err);
      setError(err instanceof Error ? err.message : 'Failed to create agent');
    } finally {
      setIsSubmitting(false);
    }
  };

  const models = PROVIDER_MODELS[formData.provider] || [];

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />
      <div className="max-w-3xl mx-auto py-12 px-4">
        {/* Header */}
        <div className="flex items-center gap-4 mb-8">
          <Link
            href="/dashboard/agents"
            className="text-foreground-secondary hover:text-foreground transition-colors"
          >
            <Icon icon="arrowLeft" size="sm" />
          </Link>
          <h1 className="text-2xl font-bold text-foreground">Create New Agent</h1>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Basic Info */}
          <div className="bg-surface border border-border rounded-lg p-6">
            <h2 className="text-lg font-medium text-foreground mb-4">Basic Information</h2>

            <div className="space-y-4">
              <div>
                <Label htmlFor="name" required className="mb-1">
                  Name
                </Label>
                <Input
                  id="name"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  required
                  maxLength={100}
                  placeholder="My AI Agent"
                />
              </div>

              <div>
                <Label htmlFor="uid" className="mb-1">
                  UID (URL-friendly identifier)
                </Label>
                <Input
                  id="uid"
                  name="uid"
                  value={formData.uid}
                  onChange={handleChange}
                  maxLength={50}
                  pattern="[a-z0-9-]+"
                  placeholder="my-ai-agent"
                  className="font-mono text-sm"
                />
                <p className="text-xs text-foreground-tertiary mt-1">
                  Used in API URLs. Lowercase letters, numbers, and hyphens only.
                </p>
              </div>

              <div>
                <Label htmlFor="description" className="mb-1">
                  Description
                </Label>
                <Textarea
                  id="description"
                  name="description"
                  value={formData.description}
                  onChange={handleChange}
                  maxLength={500}
                  rows={2}
                  resize="none"
                  placeholder="What does this agent do?"
                />
              </div>
            </div>
          </div>

          {/* Model Configuration */}
          <div className="bg-surface border border-border rounded-lg p-6">
            <h2 className="text-lg font-medium text-foreground mb-4">Model Configuration</h2>

            <div className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-2">
                <div>
                  <Label htmlFor="provider" required className="mb-1">
                    Provider
                  </Label>
                  <Select
                    id="provider"
                    name="provider"
                    value={formData.provider}
                    onChange={handleChange}
                    required
                    options={SUPPORTED_PROVIDERS.map((provider) => ({
                      value: provider,
                      label: PROVIDER_DISPLAY_NAMES[provider],
                    }))}
                  />
                </div>

                <div>
                  <Label htmlFor="modelId" required className="mb-1">
                    Model
                  </Label>
                  <Select
                    id="modelId"
                    name="modelId"
                    value={formData.modelId}
                    onChange={handleChange}
                    required
                    options={models.map((model) => ({
                      value: model.id,
                      label: model.name,
                    }))}
                  />
                </div>
              </div>

              <div>
                <Label htmlFor="systemPrompt" className="mb-1">
                  System Prompt
                </Label>
                <Textarea
                  id="systemPrompt"
                  name="systemPrompt"
                  value={formData.systemPrompt}
                  onChange={handleChange}
                  maxLength={10000}
                  rows={6}
                  resize="none"
                  placeholder="You are a helpful assistant that..."
                  className="font-mono text-sm"
                />
                <p className="text-xs text-foreground-tertiary mt-1">
                  Instructions that define how the agent behaves.
                </p>
              </div>

              <div className="grid gap-4 sm:grid-cols-3">
                <div>
                  <Label htmlFor="temperature" className="mb-1">
                    Temperature
                  </Label>
                  <Input
                    type="number"
                    id="temperature"
                    name="temperature"
                    value={formData.temperature}
                    onChange={handleChange}
                    min={0}
                    max={2}
                    step={0.1}
                  />
                  <p className="text-xs text-foreground-tertiary mt-1">
                    0 = deterministic, 2 = creative
                  </p>
                </div>

                <div>
                  <Label htmlFor="maxToolCallsPerTurn" className="mb-1">
                    Max Tool Calls
                  </Label>
                  <Input
                    type="number"
                    id="maxToolCallsPerTurn"
                    name="maxToolCallsPerTurn"
                    value={formData.maxToolCallsPerTurn}
                    onChange={handleChange}
                    min={1}
                    max={100}
                  />
                  <p className="text-xs text-foreground-tertiary mt-1">Per response turn</p>
                </div>

                <div>
                  <Label htmlFor="maxMessagesInContext" className="mb-1">
                    Context Messages
                  </Label>
                  <Input
                    type="number"
                    id="maxMessagesInContext"
                    name="maxMessagesInContext"
                    value={formData.maxMessagesInContext}
                    onChange={handleChange}
                    min={1}
                    max={100}
                  />
                  <p className="text-xs text-foreground-tertiary mt-1">
                    Recent messages to include
                  </p>
                </div>
              </div>
            </div>
          </div>

          {/* Note about tools */}
          <div className="bg-primary/5 border border-primary/20 rounded-lg p-4">
            <div className="flex items-start gap-3">
              <Icon icon="info" size="sm" className="text-primary mt-0.5" />
              <div className="text-sm">
                <p className="text-foreground">
                  You can add tools and collections to your agent after creating it.
                </p>
              </div>
            </div>
          </div>

          {/* Error */}
          {error && (
            <div className="bg-error/10 border border-error/20 rounded-lg p-4">
              <div className="flex items-start gap-3">
                <Icon icon="alertCircle" size="sm" className="text-error mt-0.5" />
                <p className="text-sm text-error">{error}</p>
              </div>
            </div>
          )}

          {/* Actions */}
          <div className="flex items-center justify-end gap-4">
            <Link href="/dashboard/agents">
              <Button type="button" variant="outline">
                Cancel
              </Button>
            </Link>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? 'Creating...' : 'Create Agent'}
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
}

  updatedAt        DateTime  @updatedAt @map("updated_at")

  @@index([userId])
  @@index([userId, namespace])
  @@index([userId, createdAt])
  @@index([expiresAt])
  @@map("memories")
}

// ============================================================================
// Execution Event Tracking (Unified per-tool execution tracking)
// ============================================================================

/// ExecutionEvent - unified tracking for tool calls, agent runs, collection use, and scenario runs
model ExecutionEvent {
  id        String @id @default(cuid())

  // Event classification
  eventType String @map("event_type") @db.VarChar(30) // 'tool_call' | 'agent_run' | 'collection_use' | 'scenario_run'
  source    String @db.VarChar(30) // 'mcp_http' | 'mcp_sse' | 'agent_chat' | 'ui_simulation' | 'scenario' | 'omega'

  // Actor (no FK constraints - tracking must never fail due to entity deletion)
  userId   String? @map("user_id")
  apiKeyId String? @map("api_key_id")

  // Entity references (no FK constraints for resilience)
  toolId       String? @map("tool_id")
  agentId      String? @map("agent_id")
  collectionId String? @map("collection_id")

  // Denormalized for fast queries without joins
  toolName    String? @map("tool_name") @db.VarChar(200)
  packageName String? @map("package_name") @db.VarChar(214)

  // Outcome
  status     String  @db.VarChar(20) // 'success' | 'error' | 'timeout'
  durationMs Int?    @map("duration_ms")

  // Token usage (for agent runs)
  tokensIn  Int? @map("tokens_in")
  tokensOut Int? @map("tokens_out")

  // Error details
  errorCode    String? @map("error_code") @db.VarChar(50)
  errorMessage String? @map("error_message") @db.Text

  // Timestamps
  createdAt DateTime @default(now()) @map("created_at")

  @@index([userId, createdAt])
  @@index([collectionId, createdAt])
  @@index([toolId, createdAt])
  @@index([eventType, createdAt])
  @@index([createdAt])
  @@map("execution_events")
}

// ============================================================================
// Search Log (Query Tracking)
// ============================================================================

/// SearchLog - tracks search queries, result counts, and latency
model SearchLog {
  id          String   @id @default(cuid())

  // Search data
  query       String   @db.VarChar(500)
  resultCount Int      @map("result_count")
  latencyMs   Int      @map("latency_ms")

  // Optional actor
  userId      String?  @map("user_id")
  sessionId   String?  @map("session_id")

  // Timestamps
  createdAt   DateTime @default(now()) @map("created_at")

  @@index([createdAt])
  @@index([query])
  @@map("search_logs")
}

