  1→import { Prisma, prisma } from '@tpmjs/db';
  2→import { UpdateAgentSchema } from '@tpmjs/types/agent';
  3→import type { NextRequest } from 'next/server';
  4→
  5→import { logActivity } from '~/lib/activity';
  6→import { authenticateRequest } from '~/lib/api-keys/middleware';
  7→import {
  8→  apiConflict,
  9→  apiForbidden,
 10→  apiInternalError,
 11→  apiNotFound,
 12→  apiSuccess,
 13→  apiUnauthorized,
 14→  apiValidationError,
 15→} from '~/lib/api-response';
 16→
 17→export const runtime = 'nodejs';
 18→export const dynamic = 'force-dynamic';
 19→
 20→type RouteContext = {
 21→  params: Promise<{ id: string }>;
 22→};
 23→
 24→/**
 25→ * GET /api/agents/[id]
 26→ * Get a single agent's details
 27→ */
 28→export async function GET(_request: NextRequest, context: RouteContext) {
 29→  const requestId = crypto.randomUUID();
 30→
 31→  try {
 32→    const authResult = await authenticateRequest();
 33→    const { id } = await context.params;
 34→
 35→    const agent = await prisma.agent.findUnique({
 36→      where: { id },
 37→      include: {
 38→        user: {
 39→          select: {
 40→            username: true,
 41→          },
 42→        },
 43→        collections: {
 44→          include: {
 45→            collection: {
 46→              select: {
 47→                id: true,
 48→                name: true,
 49→                _count: { select: { tools: true } },
 50→              },
 51→            },
 52→          },
 53→          orderBy: { position: 'asc' },
 54→          take: 50, // Limit to prevent excessive data fetch
 55→        },
 56→        tools: {
 57→          include: {
 58→            tool: {
 59→              select: {
 60→                id: true,
 61→                name: true,
 62→                description: true,
 63→                parameters: true,
 64→                package: {
 65→                  select: {
 66→                    npmPackageName: true,
 67→                    category: true,
 68→                  },
 69→                },
 70→              },
 71→            },
 72→          },
 73→          orderBy: { position: 'asc' },
 74→          take: 100, // Limit to prevent excessive data fetch
 75→        },
 76→        _count: {
 77→          select: {
 78→            tools: true,
 79→            collections: true,
 80→            conversations: true,
 81→          },
 82→        },
 83→      },
 84→    });
 85→
 86→    if (!agent) {
 87→      return apiNotFound('Agent', requestId);
 88→    }
 89→
 90→    // Check access - owner or public
 91→    const isOwner = authResult.userId === agent.userId;
 92→    if (!isOwner && !agent.isPublic) {
 93→      return apiForbidden('Access denied', requestId);
 94→    }
 95→
 96→    return apiSuccess(
 97→      {
 98→        ...agent,
 99→        isOwner,
100→        toolCount: agent._count.tools,
101→        collectionCount: agent._count.collections,
102→        conversationCount: agent._count.conversations,
103→        collections: agent.collections.map((ac) => ({
104→          id: ac.id,
105→          collectionId: ac.collectionId,
106→          position: ac.position,
107→          addedAt: ac.addedAt,
