  1→/**
  2→ * Executor Resolution Logic
  3→ *
  4→ * Handles the cascade resolution for hot-swappable executors:
  5→ * Agent Config → Collection Config → System Default
  6→ */
  7→
  8→import { executePackage } from '@tpmjs/package-executor';
  9→import type {
 10→  CreateSessionResponse,
 11→  DestroySessionResponse,
 12→  ExecuteToolRequest,
 13→  ExecuteToolResponse,
 14→  ExecutorConfig,
 15→  ExecutorHealthResponse,
 16→} from '@tpmjs/types/executor';
 17→
 18→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
 19→const MAX_RETRIES = 2;
 20→const RETRY_BASE_DELAY_MS = 1000;
 21→
 22→/**
 23→ * Retry helper with exponential backoff
 24→ */
 25→async function withRetry<T>(
 26→  fn: () => Promise<T>,
 27→  opts: { maxRetries?: number; shouldRetry?: (error: unknown) => boolean } = {}
 28→): Promise<T> {
 29→  const maxRetries = opts.maxRetries ?? MAX_RETRIES;
 30→  let lastError: unknown;
 31→
 32→  for (let attempt = 0; attempt <= maxRetries; attempt++) {
 33→    try {
 34→      return await fn();
 35→    } catch (error) {
 36→      lastError = error;
 37→      if (attempt >= maxRetries) break;
 38→      if (opts.shouldRetry && !opts.shouldRetry(error)) break;
 39→
 40→      const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
 41→      console.warn(
 42→        `[Executor] Retry ${attempt + 1}/${maxRetries} after ${delay}ms:`,
 43→        error instanceof Error ? error.message : String(error)
 44→      );
 45→      await new Promise((resolve) => setTimeout(resolve, delay));
 46→    }
 47→  }
 48→
 49→  throw lastError;
 50→}
 51→
 52→/**
 53→ * Resolve executor configuration using cascade:
 54→ * Agent Config → Collection Config → System Default
 55→ *
 56→ * @param agentConfig - Executor config from Agent (highest priority)
 57→ * @param collectionConfig - Executor config from Collection (medium priority)
 58→ * @returns Resolved executor configuration
 59→ */
 60→export function resolveExecutorConfig(
 61→  agentConfig: ExecutorConfig | null | undefined,
 62→  collectionConfig: ExecutorConfig | null | undefined
 63→): ExecutorConfig {
 64→  // Agent config takes precedence
 65→  if (agentConfig && agentConfig.type !== 'default') {
 66→    return agentConfig;
 67→  }
 68→
 69→  // Fall back to collection config
 70→  if (collectionConfig && collectionConfig.type !== 'default') {
 71→    return collectionConfig;
 72→  }
 73→
 74→  // System default
 75→  return { type: 'default' };
 76→}
 77→
 78→/**
 79→ * Parse executor config from database JSON
 80→ * Handles null/undefined and validates the shape
 81→ */
 82→export function parseExecutorConfig(
 83→  executorType: string | null | undefined,
 84→  executorConfig: unknown
 85→): ExecutorConfig | null {
 86→  if (!executorType) {
 87→    return null;
 88→  }
 89→
 90→  if (executorType === 'default') {
 91→    return { type: 'default' };
 92→  }
 93→
 94→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
 95→    const config = executorConfig as { url?: string; apiKey?: string };
 96→    if (config.url && typeof config.url === 'string') {
 97→      return {
 98→        type: 'custom_url',
 99→        url: config.url,
100→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
101→      };
102→    }
103→  }
104→
105→  return null;
106→}
107→
108→/**
109→ * Execute a tool using a custom URL executor
110→ */
111→async function executeWithCustomUrl(
112→  url: string,
113→  apiKey: string | undefined,
114→  request: ExecuteToolRequest,
115→  timeout: number = DEFAULT_TIMEOUT
116→): Promise<ExecuteToolResponse> {
117→  const startTime = Date.now();
118→
119→  const headers: Record<string, string> = {
120→    'Content-Type': 'application/json',
121→  };
122→
123→  if (apiKey) {
124→    headers.Authorization = `Bearer ${apiKey}`;
125→  }
126→
127→  try {
128→    const controller = new AbortController();
129→    const timeoutId = setTimeout(() => controller.abort(), timeout);
130→
131→    const response = await fetch(`${url}/execute-tool`, {
132→      method: 'POST',
133→      headers,
134→      body: JSON.stringify(request),
135→      signal: controller.signal,
136→    });
137→
138→    clearTimeout(timeoutId);
139→
140→    const executionTimeMs = Date.now() - startTime;
141→
142→    if (!response.ok) {
143→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
144→        error?: string;
145→      };
146→      return {
147→        success: false,
148→        error: errorData.error || `Executor error: ${response.status}`,
149→        executionTimeMs,
150→      };
151→    }
152→
153→    const result = (await response.json()) as ExecuteToolResponse;
154→
155→    return {
156→      success: result.success,
157→      output: result.output,
158→      error: result.error,
159→      executionTimeMs: result.executionTimeMs || executionTimeMs,
160→    };
161→  } catch (error) {
162→    const executionTimeMs = Date.now() - startTime;
163→
164→    if (error instanceof Error && error.name === 'AbortError') {
165→      return {
166→        success: false,
167→        error: 'Execution timeout',
168→        executionTimeMs,
169→      };
170→    }
171→
172→    return {
173→      success: false,
174→      error: error instanceof Error ? error.message : String(error),
175→      executionTimeMs,
176→    };
177→  }
178→}
