180→// =============================================================================
181→// Sandbox Session Management
182→// =============================================================================
183→
184→/**
185→ * Get sandbox configuration from environment variables
186→ */
187→export function getSandboxConfig(): { url: string | null; apiKey: string | undefined } {
188→  return {
189→    url: process.env.AGENT_SANDBOX_URL || null,
190→    apiKey: process.env.AGENT_SANDBOX_API_KEY || undefined,
191→  };
192→}
193→
194→/**
195→ * Create or resume a sandbox session (idempotent)
196→ * If the session already exists, extends its TTL and returns it.
197→ */
198→export async function createSandboxSession(
199→  url: string,
200→  apiKey: string | undefined,
201→  sessionId: string,
202→  timeoutSeconds?: number
203→): Promise<CreateSessionResponse> {
204→  return withRetry(
205→    async () => {
206→      const headers: Record<string, string> = { 'Content-Type': 'application/json' };
207→      if (apiKey) {
208→        headers.Authorization = `Bearer ${apiKey}`;
209→      }
210→
211→      const controller = new AbortController();
212→      const timeoutId = setTimeout(() => controller.abort(), 15000);
213→
214→      try {
215→        const response = await fetch(`${url}/sessions`, {
216→          method: 'POST',
217→          headers,
218→          body: JSON.stringify({ sessionId, timeoutSeconds }),
219→          signal: controller.signal,
220→        });
221→
222→        clearTimeout(timeoutId);
223→
224→        if (response.status === 429) {
225→          throw new Error('Sandbox at capacity (429). Retrying...');
226→        }
227→
228→        if (!response.ok) {
229→          const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
230→            error?: string;
231→          };
232→          throw new Error(
233→            errorData.error || `Failed to create sandbox session: ${response.status}`
234→          );
235→        }
236→
237→        return (await response.json()) as CreateSessionResponse;
238→      } catch (error) {
239→        clearTimeout(timeoutId);
240→        if (error instanceof Error && error.name === 'AbortError') {
241→          throw new Error('Sandbox session creation timed out');
242→        }
243→        throw error;
244→      }
245→    },
246→    {
247→      shouldRetry: (error) => {
248→        const msg = error instanceof Error ? error.message : String(error);
249→        // Retry on network errors, timeouts, and capacity issues
250→        return (
251→          msg.includes('timed out') ||
252→          msg.includes('429') ||
253→          msg.includes('ECONNREFUSED') ||
254→          msg.includes('fetch failed')
255→        );
256→      },
257→    }
258→  );
259→}
260→
261→/**
262→ * Destroy a sandbox session (fire-and-forget safe)
263→ * Returns gracefully even if the session doesn't exist.
264→ */
265→export async function destroySandboxSession(
266→  url: string,
267→  apiKey: string | undefined,
268→  sessionId: string
269→): Promise<DestroySessionResponse> {
270→  const headers: Record<string, string> = {};
271→  if (apiKey) {
272→    headers.Authorization = `Bearer ${apiKey}`;
273→  }
274→
275→  try {
276→    const controller = new AbortController();
277→    const timeoutId = setTimeout(() => controller.abort(), 10000);
278→
279→    const response = await fetch(`${url}/sessions/${encodeURIComponent(sessionId)}`, {
280→      method: 'DELETE',
281→      headers,
282→      signal: controller.signal,
283→    });
284→
285→    clearTimeout(timeoutId);
286→
287→    if (!response.ok && response.status !== 404) {
288→      return { sessionId, destroyed: false };
289→    }
290→
291→    return (await response
292→      .json()
293→      .catch(() => ({ sessionId, destroyed: true }))) as DestroySessionResponse;
294→  } catch {
295→    // Fire-and-forget: don't throw on cleanup failures
296→    return { sessionId, destroyed: false };
297→  }
298→}
