'use client';

import { Handle, Position, type NodeProps } from '@xyflow/react';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Badge } from '@tpmjs/ui/Badge/Badge';

export interface TriggerNodeData {
  label: string;
  triggerType?: string;
  status?: 'idle' | 'running' | 'completed' | 'failed';
  [key: string]: unknown;
