      ...pastRef.current.slice(-MAX_HISTORY + 1),
      { nodes: structuredClone(nodes), edges: structuredClone(edges) },
    ];
    futureRef.current = [];
    setRevision((r) => r + 1);
  }, []);

  const undo = useCallback((): GraphState | null => {
