 84→
 85→export function WorkflowCanvas({ workflowId }: WorkflowCanvasProps): React.ReactElement {
 86→  const [workflow, setWorkflow] = useState<WorkflowData | null>(null);
 87→  const [loading, setLoading] = useState(true);
 88→  const [nodes, setNodes, onNodesChange] = useNodesState([]);
 89→  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
 90→  const [selectedNodeId, setSelectedNodeId] = useState<string | null>(null);
 91→  const [paletteCollapsed, setPaletteCollapsed] = useState(false);
 92→  const [activeTab, setActiveTab] = useState<'canvas' | 'runs'>('canvas');
 93→  const [saveStatus, setSaveStatus] = useState<'saved' | 'saving' | 'unsaved' | 'error'>('saved');
 94→  const reactFlowInstance = useRef<ReactFlowInstance | null>(null);
 95→  const saveTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 96→  const isInitialLoadRef = useRef(true);
 97→
 98→  const { isRunning, nodeStatuses, runWorkflow } = useWorkflowExecution(workflowId);
 99→  const { pushState, undo, redo, canUndo, canRedo } = useUndoRedo();
100→
101→  // Load workflow data
102→  useEffect(() => {
103→    fetch(`/api/workflows/${workflowId}`)
104→      .then((res) => res.json())
105→      .then((result) => {
106→        if (result.success) {
107→          const wf = result.data;
108→          setWorkflow(wf);
109→
110→          // Build a map from DB node ID to React Flow nodeId
111→          const dbIdToNodeId = new Map<string, string>();
112→          for (const node of wf.nodes) {
113→            dbIdToNodeId.set(node.id, node.nodeId);
114→          }
115→
116→          // Convert DB nodes to React Flow nodes
117→          const rfNodes: Node[] = wf.nodes.map(
118→            (n: WorkflowData['nodes'][0]) => ({
119→              id: n.nodeId,
120→              type: n.type,
121→              position: { x: n.positionX, y: n.positionY },
122→              data: {
123→                label: n.label,
124→                nodeType: n.type,
125→                config: n.config,
126→                toolId: n.toolId,
127→                agentId: n.agentId,
128→                tool: n.tool,
129→                agent: n.agent,
130→                triggerType: n.type === 'TRIGGER' ? wf.triggerType : undefined,
131→                toolName: n.tool
132→                  ? (n.tool as Record<string, unknown>).name
133→                  : undefined,
134→                packageName: n.tool
135→                  ? ((n.tool as Record<string, unknown>).package as Record<string, unknown>)
136→                      ?.npmPackageName
137→                  : undefined,
138→                agentName: n.agent
139→                  ? (n.agent as Record<string, unknown>).name
140→                  : undefined,
141→                modelId: n.agent
142→                  ? (n.agent as Record<string, unknown>).modelId
143→                  : undefined,
144→              },
145→            })
146→          );
147→
148→          // Convert DB edges to React Flow edges
149→          const rfEdges: Edge[] = wf.edges.map(
150→            (e: WorkflowData['edges'][0]) => ({
151→              id: e.edgeId,
152→              source: dbIdToNodeId.get(e.sourceNodeId) || e.sourceNodeId,
153→              target: dbIdToNodeId.get(e.targetNodeId) || e.targetNodeId,
154→              sourceHandle: e.sourceHandle || undefined,
155→              targetHandle: e.targetHandle || undefined,
156→              type: 'data',
157→              data: { dataMapping: e.dataMapping },
158→            })
159→          );
160→
161→          setNodes(rfNodes);
162→          setEdges(rfEdges);
163→
164→          // Restore viewport
165→          if (wf.canvasViewport && reactFlowInstance.current) {
166→            reactFlowInstance.current.setViewport(wf.canvasViewport);
167→          }
168→        }
169→      })
170→      .catch(console.error)
171→      .finally(() => {
172→        setLoading(false);
173→        // Allow initial load to complete before enabling auto-save
174→        setTimeout(() => {
175→          isInitialLoadRef.current = false;
176→        }, 500);
177→      });
178→  }, [workflowId, setNodes, setEdges]);
179→
180→  // Debounced auto-save
181→  const saveGraph = useCallback(() => {
182→    if (isInitialLoadRef.current) return;
183→    setSaveStatus('saving');
184→
185→    const currentNodes = nodes.map((n) => {
186→      const data = n.data as Record<string, unknown>;
187→      return {
188→        nodeId: n.id,
189→        type: data.nodeType as string,
190→        label: (data.label as string) || n.id,
191→        positionX: n.position.x,
192→        positionY: n.position.y,
193→        config: data.config || null,
194→        toolId: data.toolId || null,
195→        agentId: data.agentId || null,
196→      };
197→    });
198→
199→    const currentEdges = edges.map((e) => ({
200→      edgeId: e.id,
201→      sourceNodeId: e.source,
202→      targetNodeId: e.target,
203→      sourceHandle: e.sourceHandle || null,
204→      targetHandle: e.targetHandle || null,
205→      dataMapping: (e.data as Record<string, unknown>)?.dataMapping || null,
206→    }));
207→
208→    const viewport = reactFlowInstance.current?.getViewport();
209→
210→    fetch(`/api/workflows/${workflowId}/graph`, {
211→      method: 'PUT',
212→      headers: { 'Content-Type': 'application/json' },
213→      body: JSON.stringify({
214→        nodes: currentNodes,
215→        edges: currentEdges,
216→        canvasViewport: viewport || null,
217→      }),
218→    })
219→      .then((res) => res.json())
220→      .then((result) => {
221→        setSaveStatus(result.success ? 'saved' : 'error');
222→      })
223→      .catch(() => setSaveStatus('error'));
224→  }, [nodes, edges, workflowId]);
225→
226→  // Trigger auto-save on changes
227→  useEffect(() => {
228→    if (isInitialLoadRef.current) return;
229→    setSaveStatus('unsaved');
230→
231→    if (saveTimeoutRef.current) {
232→      clearTimeout(saveTimeoutRef.current);
233→    }
234→    saveTimeoutRef.current = setTimeout(saveGraph, 2000);
235→
236→    return () => {
237→      if (saveTimeoutRef.current) {
238→        clearTimeout(saveTimeoutRef.current);
239→      }
240→    };
241→  }, [nodes, edges, saveGraph]);
242→
243→  // Update node statuses during execution
244→  useEffect(() => {
245→    if (nodeStatuses.size === 0) return;
246→    setNodes((nds) =>
247→      nds.map((n) => {
248→        const status = nodeStatuses.get(n.id);
249→        if (status) {
250→          return {
251→            ...n,
252→            data: { ...n.data, status: status.status },
253→          };
254→        }
255→        return n;
256→      })
257→    );
258→  }, [nodeStatuses, setNodes]);
259→
260→  const onConnect = useCallback(
261→    (connection: Connection) => {
262→      setEdges((eds) =>
