 26→  id: string;
 27→  name: string;
 28→  description: string | null;
 29→  provider: string;
 30→  modelId: string;
 31→}
 32→
 33→const LOGIC_ITEMS: PaletteItem[] = [
 34→  {
 35→    type: 'TRIGGER',
 36→    label: 'Trigger',
 37→    description: 'Workflow entry point',
 38→    icon: 'send',
 39→    color: 'text-blue-500',
 40→  },
 41→  {
 42→    type: 'CONDITION',
 43→    label: 'Condition',
 44→    description: 'Branch based on condition',
 45→    icon: 'gitFork',
 46→    color: 'text-amber-500',
 47→  },
 48→  {
 49→    type: 'LOOP',
 50→    label: 'Loop',
 51→    description: 'Iterate over an array',
 52→    icon: 'loader',
 53→    color: 'text-teal-500',
 54→  },
 55→  {
 56→    type: 'TRANSFORM',
 57→    label: 'Transform',
 58→    description: 'Map and reshape data',
