 75→  },
 76→];
 77→
 78→interface NodePaletteProps {
 79→  collapsed?: boolean;
 80→  onToggle?: () => void;
 81→}
 82→
 83→export function NodePalette({ collapsed, onToggle }: NodePaletteProps): React.ReactElement {
 84→  const [search, setSearch] = useState('');
 85→  const [tools, setTools] = useState<ToolResult[]>([]);
 86→  const [agents, setAgents] = useState<AgentResult[]>([]);
 87→  const [toolsLoading, setToolsLoading] = useState(false);
 88→
 89→  // Fetch user's agents on mount
 90→  useEffect(() => {
 91→    fetch('/api/agents?limit=50')
 92→      .then((res) => res.json())
 93→      .then((data) => {
 94→        if (data.success) setAgents(data.data);
 95→      })
 96→      .catch(() => {});
 97→  }, []);
 98→
 99→  // Debounced tool search
100→  useEffect(() => {
101→    if (!search || search.length < 2) {
102→      setTools([]);
103→      return;
104→    }
105→
106→    setToolsLoading(true);
107→    const timer = setTimeout(() => {
108→      fetch(`/api/tools/search?q=${encodeURIComponent(search)}&limit=10`)
109→        .then((res) => res.json())
110→        .then((data) => {
111→          if (data.success) setTools(data.data || []);
112→        })
113→        .catch(() => {})
114→        .finally(() => setToolsLoading(false));
115→    }, 300);
116→
117→    return () => clearTimeout(timer);
118→  }, [search]);
119→
120→  const onDragStart = useCallback(
121→    (event: React.DragEvent, item: PaletteItem) => {
122→      event.dataTransfer.setData('application/workflow-node', JSON.stringify(item));
123→      event.dataTransfer.effectAllowed = 'move';
124→    },
125→    []
126→  );
127→
128→  if (collapsed) {
129→    return (
130→      <div className="w-10 border-r border-border bg-surface flex flex-col items-center py-2">
131→        <button
132→          type="button"
133→          onClick={onToggle}
134→          className="p-1.5 rounded hover:bg-surface-secondary transition-colors"
135→          title="Expand palette"
136→        >
137→          <Icon icon="chevronRight" size="sm" className="text-foreground-secondary" />
138→        </button>
139→      </div>
140→    );
141→  }
142→
143→  const filteredLogicItems = search
144→    ? LOGIC_ITEMS.filter(
145→        (item) =>
146→          item.label.toLowerCase().includes(search.toLowerCase()) ||
147→          item.description.toLowerCase().includes(search.toLowerCase())
148→      )
149→    : LOGIC_ITEMS;
150→
151→  const filteredAgents = search
152→    ? agents.filter(
153→        (a) =>
154→          a.name.toLowerCase().includes(search.toLowerCase()) ||
155→          a.description?.toLowerCase().includes(search.toLowerCase())
156→      )
157→    : agents;
158→
159→  return (
160→    <div className="w-[220px] border-r border-border bg-surface flex flex-col overflow-hidden">
161→      <div className="px-3 py-2 border-b border-border flex items-center justify-between">
162→        <span className="text-xs font-semibold text-foreground-tertiary uppercase tracking-wider">
163→          Nodes
164→        </span>
165→        {onToggle && (
166→          <button
167→            type="button"
168→            onClick={onToggle}
169→            className="p-1 rounded hover:bg-surface-secondary transition-colors"
170→          >
171→            <Icon icon="chevronLeft" size="xs" className="text-foreground-secondary" />
172→          </button>
173→        )}
174→      </div>
175→
176→      <div className="px-3 py-2">
177→        <Input
178→          value={search}
179→          onChange={(e) => setSearch(e.target.value)}
180→          placeholder="Search nodes..."
181→          className="text-xs h-7"
182→        />
183→      </div>
184→
185→      <div className="flex-1 overflow-y-auto px-2 pb-2 space-y-3">
186→        {/* Logic Nodes */}
187→        {filteredLogicItems.length > 0 && (
188→          <PaletteSection title="Logic">
189→            {filteredLogicItems.map((item) => (
190→              <PaletteItemRow key={item.type} item={item} onDragStart={onDragStart} />
191→            ))}
192→          </PaletteSection>
193→        )}
194→
195→        {/* Tools */}
196→        {(search.length >= 2 || tools.length > 0) && (
197→          <PaletteSection title="Tools">
198→            {toolsLoading ? (
199→              <p className="text-xs text-foreground-tertiary px-2 py-1">Searching...</p>
200→            ) : tools.length > 0 ? (
201→              tools.map((tool) => (
202→                <PaletteItemRow
203→                  key={tool.id}
204→                  item={{
205→                    type: 'TOOL',
206→                    label: tool.name,
207→                    description: tool.package.npmPackageName,
208→                    icon: 'puzzle',
209→                    color: 'text-purple-500',
210→                    toolId: tool.id,
211→                    packageName: tool.package.npmPackageName,
212→                  }}
213→                  onDragStart={onDragStart}
214→                />
215→              ))
216→            ) : search.length >= 2 ? (
217→              <p className="text-xs text-foreground-tertiary px-2 py-1">No tools found</p>
218→            ) : null}
219→          </PaletteSection>
220→        )}
221→
222→        {/* Agents */}
223→        {filteredAgents.length > 0 && (
224→          <PaletteSection title="Agents">
225→            {filteredAgents.map((agent) => (
226→              <PaletteItemRow
227→                key={agent.id}
228→                item={{
229→                  type: 'AGENT',
230→                  label: agent.name,
231→                  description: agent.modelId,
232→                  icon: 'terminal',
233→                  color: 'text-green-500',
234→                  agentId: agent.id,
235→                }}
236→                onDragStart={onDragStart}
237→              />
238→            ))}
239→          </PaletteSection>
240→        )}
241→      </div>
242→    </div>
243→  );
244→}
245→
246→function PaletteSection({
247→  title,
248→  children,
249→}: {
250→  title: string;
251→  children: React.ReactNode;
252→}) {
253→  return (
254→    <div>
255→      <h3 className="text-[10px] font-semibold text-foreground-tertiary uppercase tracking-wider px-1 mb-1">
256→        {title}
257→      </h3>
258→      <div className="space-y-0.5">{children}</div>
259→    </div>
260→  );
261→}
262→
263→function PaletteItemRow({
264→  item,
265→  onDragStart,
266→}: {
267→  item: PaletteItem;
268→  onDragStart: (event: React.DragEvent, item: PaletteItem) => void;
269→}) {
270→  return (
271→    <div
272→      draggable
273→      onDragStart={(e) => onDragStart(e, item)}
274→      className="flex items-center gap-2 px-2 py-1.5 rounded cursor-grab hover:bg-surface-secondary transition-colors active:cursor-grabbing"
275→    >
276→      <Icon icon={item.icon} size="xs" className={item.color} />
277→      <div className="min-w-0 flex-1">
278→        <p className="text-xs font-medium text-foreground truncate">{item.label}</p>
279→        <p className="text-[10px] text-foreground-tertiary truncate">{item.description}</p>
280→      </div>
281→    </div>
282→  );
283→}
