  1→import { prisma } from '@tpmjs/db';
  2→import { type NextRequest, NextResponse } from 'next/server';
  3→import { z } from 'zod/v4';
  4→
  5→import { logActivity } from '~/lib/activity';
  6→import { authenticateRequest } from '~/lib/api-keys/middleware';
  7→
  8→export const runtime = 'nodejs';
  9→export const maxDuration = 60;
 10→
 11→const MAX_WORKFLOWS_PER_USER = 50;
 12→
 13→function generateUid(name: string): string {
 14→  return name
 15→    .toLowerCase()
 16→    .replace(/[^a-z0-9\s-]/g, '')
 17→    .replace(/\s+/g, '-')
 18→    .replace(/-+/g, '-')
 19→    .replace(/^-|-$/g, '')
 20→    .slice(0, 50);
 21→}
 22→
 23→const CreateWorkflowSchema = z.object({
 24→  name: z.string().min(1).max(100),
 25→  uid: z.string().max(100).optional(),
 26→  description: z.string().max(2000).optional(),
 27→  triggerType: z.enum(['MANUAL', 'WEBHOOK', 'SCHEDULE']).optional(),
 28→});
 29→
 30→/**
 31→ * GET /api/workflows
 32→ * List all workflows owned by the authenticated user
 33→ */
 34→export async function GET(request: NextRequest): Promise<NextResponse> {
 35→  try {
 36→    const authResult = await authenticateRequest();
 37→    if (!authResult.authenticated || !authResult.userId) {
 38→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 39→    }
 40→
 41→    const { searchParams } = new URL(request.url);
 42→    const limit = Math.min(Number.parseInt(searchParams.get('limit') || '20', 10), 50);
 43→    const offset = Number.parseInt(searchParams.get('offset') || '0', 10);
 44→
 45→    const workflows = await prisma.workflow.findMany({
 46→      where: { userId: authResult.userId },
 47→      select: {
 48→        id: true,
 49→        uid: true,
 50→        name: true,
 51→        description: true,
 52→        status: true,
 53→        triggerType: true,
 54→        executionCount: true,
 55→        lastExecutedAt: true,
 56→        version: true,
 57→        createdAt: true,
 58→        updatedAt: true,
 59→        _count: {
 60→          select: {
 61→            nodes: true,
 62→            edges: true,
 63→          },
 64→        },
 65→      },
 66→      orderBy: { updatedAt: 'desc' },
 67→      take: limit + 1,
 68→      skip: offset,
 69→    });
 70→
 71→    const hasMore = workflows.length > limit;
 72→    const data = hasMore ? workflows.slice(0, limit) : workflows;
 73→
 74→    return NextResponse.json({
 75→      success: true,
 76→      data: data.map((w) => ({
 77→        ...w,
 78→        nodeCount: w._count.nodes,
 79→        edgeCount: w._count.edges,
 80→        _count: undefined,
 81→      })),
 82→      pagination: {
 83→        limit,
 84→        offset,
 85→        count: data.length,
 86→        hasMore,
 87→      },
 88→    });
 89→  } catch (error) {
 90→    console.error('Failed to list workflows:', error);
 91→    return NextResponse.json(
 92→      { success: false, error: 'Failed to list workflows' },
 93→      { status: 500 }
 94→    );
 95→  }
 96→}
 97→
 98→/**
 99→ * POST /api/workflows
100→ * Create a new workflow
101→ */
102→export async function POST(request: NextRequest): Promise<NextResponse> {
103→  try {
104→    const authResult = await authenticateRequest();
105→    if (!authResult.authenticated || !authResult.userId) {
106→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
107→    }
108→    const userId = authResult.userId;
109→
110→    const body = await request.json();
111→    const parsed = CreateWorkflowSchema.safeParse(body);
112→    if (!parsed.success) {
113→      return NextResponse.json(
114→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
115→        { status: 400 }
116→      );
117→    }
118→
119→    // Check workflow limit
120→    const workflowCount = await prisma.workflow.count({
121→      where: { userId },
122→    });
123→    if (workflowCount >= MAX_WORKFLOWS_PER_USER) {
124→      return NextResponse.json(
125→        { success: false, error: `Maximum ${MAX_WORKFLOWS_PER_USER} workflows allowed` },
126→        { status: 400 }
127→      );
128→    }
129→
130→    const { name, uid, description, triggerType } = parsed.data;
131→
132→    // Generate UID if not provided
133→    let finalUid = uid || generateUid(name);
134→
135→    // Check for UID uniqueness
136→    const existingByUid = await prisma.workflow.findUnique({ where: { uid: finalUid } });
137→    if (existingByUid) {
138→      finalUid = `${finalUid}-${Math.random().toString(36).slice(2, 6)}`;
139→    }
140→
141→    // Check for name uniqueness within user's workflows
142→    const existingByName = await prisma.workflow.findFirst({
143→      where: { userId, name },
144→    });
145→    if (existingByName) {
146→      return NextResponse.json(
147→        { success: false, error: 'A workflow with this name already exists' },
148→        { status: 409 }
149→      );
150→    }
151→
152→    const workflow = await prisma.workflow.create({
153→      data: {
154→        userId,
155→        uid: finalUid,
156→        name,
157→        description,
158→        triggerType: triggerType || 'MANUAL',
159→        status: 'DRAFT',
160→      },
161→      select: {
162→        id: true,
163→        uid: true,
164→        name: true,
165→        description: true,
166→        status: true,
167→        triggerType: true,
168→        version: true,
169→        createdAt: true,
170→        updatedAt: true,
171→      },
172→    });
173→
