 35→  sourceNodeId: z.string(),
 36→  targetNodeId: z.string(),
 37→  sourceHandle: z.string().max(50).optional().nullable(),
 38→  targetHandle: z.string().max(50).optional().nullable(),
 39→  dataMapping: z.record(z.unknown()).optional().nullable(),
 40→});
 41→
 42→const SaveGraphSchema = z.object({
 43→  nodes: z.array(NodeSchema),
 44→  edges: z.array(EdgeSchema),
 45→  canvasViewport: z
 46→    .object({
 47→      x: z.number(),
 48→      y: z.number(),
 49→      zoom: z.number(),
 50→    })
 51→    .optional()
 52→    .nullable(),
 53→});
 54→
 55→/**
 56→ * PUT /api/workflows/[id]/graph
 57→ * Bulk save all nodes and edges (replace strategy)
 58→ */
 59→export async function PUT(request: NextRequest, context: RouteContext) {
 60→  const requestId = crypto.randomUUID();
 61→
 62→  try {
 63→    const authResult = await authenticateRequest();
 64→    if (!authResult.authenticated || !authResult.userId) {
 65→      return apiUnauthorized('Authentication required', requestId);
 66→    }
 67→
 68→    const { id } = await context.params;
 69→    const body = await request.json();
 70→    const parsed = SaveGraphSchema.safeParse(body);
 71→    if (!parsed.success) {
 72→      return apiValidationError(
 73→        'Invalid graph data',
 74→        { errors: parsed.error.flatten().fieldErrors },
 75→        requestId
 76→      );
 77→    }
 78→
 79→    // Check ownership
 80→    const existing = await prisma.workflow.findUnique({
 81→      where: { id },
 82→      select: { userId: true, version: true },
 83→    });
 84→    if (!existing) {
 85→      return apiNotFound('Workflow', requestId);
 86→    }
 87→    if (existing.userId !== authResult.userId) {
 88→      return apiForbidden('Access denied', requestId);
 89→    }
 90→
 91→    const { nodes, edges, canvasViewport } = parsed.data;
 92→
 93→    // Transaction: delete all existing nodes/edges, create new ones, increment version
 94→    const result = await prisma.$transaction(async (tx) => {
 95→      // Delete existing edges first (they reference nodes)
 96→      await tx.workflowEdge.deleteMany({ where: { workflowId: id } });
 97→      // Delete existing nodes
 98→      await tx.workflowNode.deleteMany({ where: { workflowId: id } });
 99→
100→      // Create new nodes
101→      if (nodes.length > 0) {
102→        await tx.workflowNode.createMany({
103→          data: nodes.map((node) => ({
104→            workflowId: id,
105→            nodeId: node.nodeId,
106→            type: node.type,
107→            label: node.label,
108→            positionX: node.positionX,
109→            positionY: node.positionY,
110→            config: node.config ?? undefined,
111→            toolId: node.toolId ?? undefined,
112→            agentId: node.agentId ?? undefined,
113→          })),
114→        });
115→      }
116→
117→      // Look up created node IDs for edge foreign keys
118→      const createdNodes = await tx.workflowNode.findMany({
119→        where: { workflowId: id },
120→        select: { id: true, nodeId: true },
121→      });
122→      const nodeIdMap = new Map(createdNodes.map((n) => [n.nodeId, n.id]));
123→
124→      // Create new edges
125→      if (edges.length > 0) {
126→        const edgeData = edges
127→          .map((edge) => {
128→            const sourceId = nodeIdMap.get(edge.sourceNodeId);
129→            const targetId = nodeIdMap.get(edge.targetNodeId);
130→            if (!sourceId || !targetId) return null;
131→            return {
132→              workflowId: id,
133→              edgeId: edge.edgeId,
134→              sourceNodeId: sourceId,
135→              targetNodeId: targetId,
136→              sourceHandle: edge.sourceHandle ?? undefined,
137→              targetHandle: edge.targetHandle ?? undefined,
138→              dataMapping: edge.dataMapping ?? undefined,
139→            };
140→          })
141→          .filter((e): e is NonNullable<typeof e> => e !== null);
142→
143→        if (edgeData.length > 0) {
144→          await tx.workflowEdge.createMany({ data: edgeData });
145→        }
146→      }
147→
148→      // Update workflow version and canvas viewport
149→      const updated = await tx.workflow.update({
150→        where: { id },
151→        data: {
152→          version: existing.version + 1,
153→          canvasViewport: canvasViewport ?? undefined,
154→        },
155→        select: {
156→          id: true,
157→          version: true,
158→          updatedAt: true,
159→        },
160→      });
161→
162→      return updated;
163→    });
164→
165→    return apiSuccess(
166→      {
167→        ...result,
168→        nodeCount: nodes.length,
169→        edgeCount: edges.length,
170→      },
171→      { requestId }
172→    );
173→  } catch (error) {
174→    console.error('Failed to save workflow graph:', error);
175→    return apiInternalError('Failed to save workflow graph', requestId);
176→  }
177→}
