 49→function formatRelativeTime(dateString: string): string {
 50→  const date = new Date(dateString);
 51→  const now = new Date();
 52→  const diffMs = now.getTime() - date.getTime();
 53→  const diffMins = Math.floor(diffMs / 60000);
 54→  if (diffMins < 1) return 'Just now';
 55→  if (diffMins < 60) return `${diffMins}m ago`;
 56→  const diffHours = Math.floor(diffMins / 60);
 57→  if (diffHours < 24) return `${diffHours}h ago`;
 58→  const diffDays = Math.floor(diffHours / 24);
 59→  if (diffDays < 7) return `${diffDays}d ago`;
 60→  return formatDate(dateString);
 61→}
