 1→/**
 2→ * Agent node executor - one-shot text generation using an agent configuration
 3→ */
 4→import { prisma } from '@tpmjs/db';
 5→import { generateText } from 'ai';
 6→import { resolveTemplate } from '../data-mapping';
 7→
 8→// Lazy model resolution to avoid importing all SDKs at once
 9→async function getModel(provider: string, modelId: string) {
10→  switch (provider) {
11→    case 'OPENAI': {
12→      const { openai } = await import('@ai-sdk/openai');
13→      return openai(modelId);
14→    }
15→    case 'ANTHROPIC': {
16→      const { anthropic } = await import('@ai-sdk/anthropic');
17→      return anthropic(modelId);
18→    }
19→    case 'GOOGLE': {
20→      const { google } = await import('@ai-sdk/google');
21→      return google(modelId);
22→    }
23→    case 'GROQ': {
24→      const { groq } = await import('@ai-sdk/groq');
25→      return groq(modelId);
26→    }
27→    case 'MISTRAL': {
28→      const { mistral } = await import('@ai-sdk/mistral');
29→      return mistral(modelId);
30→    }
31→    default:
32→      throw new Error(`Unsupported provider: ${provider}`);
33→  }
34→}
35→
36→export async function executeAgent(
37→  config: Record<string, unknown>,
38→  input: unknown,
39→  agentId: string
40→): Promise<unknown> {
41→  const agent = await prisma.agent.findUnique({
42→    where: { id: agentId },
43→    select: {
44→      provider: true,
45→      modelId: true,
46→      systemPrompt: true,
47→      temperature: true,
48→    },
49→  });
50→
51→  if (!agent) {
52→    throw new Error(`Agent not found: ${agentId}`);
53→  }
54→
55→  // Resolve prompt template
56→  let prompt = (config.prompt as string) || '';
57→  if (prompt.includes('{{')) {
58→    const resolved = resolveTemplate(prompt, new Map(), input);
59→    prompt = typeof resolved === 'string' ? resolved : JSON.stringify(resolved);
60→  }
61→
62→  // If no prompt configured, use the input as the prompt
63→  if (!prompt && input) {
64→    prompt = typeof input === 'string' ? input : JSON.stringify(input);
65→  }
66→
67→  const model = await getModel(agent.provider, agent.modelId);
68→
69→  const result = await generateText({
70→    model,
71→    system: agent.systemPrompt || undefined,
72→    prompt,
73→    temperature: agent.temperature ?? 0.7,
74→    maxTokens: 4096,
75→  });
76→
77→  return {
78→    text: result.text,
