'use client';

import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Input } from '@tpmjs/ui/Input/Input';
import { Label } from '@tpmjs/ui/Label/Label';
import type { Node } from '@xyflow/react';
import { useEffect, useState } from 'react';
import { SchemaFormGenerator } from '../SchemaFormGenerator';

interface ToolNodeInspectorProps {
  node: Node;
  onUpdate: (nodeId: string, data: Record<string, unknown>) => void;
  nodes: Node[];
  edges: Array<{ source: string; target: string; sourceHandle?: string | null }>;
}

interface ToolDetail {
  id: string;
  name: string;
  description: string;
  inputSchema: Record<string, unknown> | null;
  importHealth: string | null;
  package: { npmPackageName: string; category: string };
}

export function ToolNodeInspector({
  node,
  onUpdate,
  nodes,
  edges,
}: ToolNodeInspectorProps): React.ReactElement {
  const data = node.data as Record<string, unknown>;
  const config = (data.config as Record<string, unknown>) || {};
  const toolId = data.toolId as string | undefined;
  const [tool, setTool] = useState<ToolDetail | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!toolId) return;
    setLoading(true);
    fetch(`/api/tools/${toolId}`)
      .then((res) => res.json())
      .then((result) => {
        if (result.success) setTool(result.data);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [toolId]);

  const updateConfig = (key: string, value: unknown) => {
    onUpdate(node.id, {
      ...data,
      config: { ...config, params: { ...(config.params as Record<string, unknown>), [key]: value } },
    });
  };

  if (!toolId) {
    return (
      <div className="text-sm text-foreground-tertiary">
        No tool selected. Drag a tool from the palette.
      </div>
    );
  }

  if (loading) {
    return <div className="text-sm text-foreground-tertiary">Loading tool details...</div>;
  }

  return (
    <div className="space-y-4">
      {tool && (
        <>
          <div className="bg-surface-secondary rounded-lg p-3">
            <p className="text-xs font-medium text-foreground">{tool.name}</p>
            <p className="text-xs text-foreground-tertiary mt-0.5">{tool.package.npmPackageName}</p>
            {tool.description && (
              <p className="text-xs text-foreground-secondary mt-1 line-clamp-2">
                {tool.description}
              </p>
            )}
            <div className="flex gap-2 mt-2">
              <Badge variant="outline" size="sm">
                {tool.package.category}
              </Badge>
              {tool.importHealth && (
                <Badge
                  variant={tool.importHealth === 'HEALTHY' ? 'default' : 'secondary'}
                  size="sm"
                >
                  {tool.importHealth.toLowerCase()}
                </Badge>
              )}
            </div>
          </div>

          {/* Parameters form from schema */}
          {tool.inputSchema ? (
            <div>
              <Label className="mb-2 text-xs">Parameters</Label>
              <SchemaFormGenerator
                schema={tool.inputSchema}
                values={(config.params as Record<string, unknown>) || {}}
                onChange={updateConfig}
                nodes={nodes}
                edges={edges}
                currentNodeId={node.id}
              />
            </div>
          ) : (
            <div className="text-xs text-foreground-tertiary">
              No input schema available for this tool.
            </div>
          )}
        </>
      )}
    </div>
  );
}

'use client';

import { Button } from '@tpmjs/ui/Button/Button';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Input } from '@tpmjs/ui/Input/Input';
import { Label } from '@tpmjs/ui/Label/Label';
import type { Node } from '@xyflow/react';

interface TransformNodeInspectorProps {
  node: Node;
  onUpdate: (nodeId: string, data: Record<string, unknown>) => void;
  nodes: Node[];
  edges: Array<{ source: string; target: string; sourceHandle?: string | null }>;
}

interface FieldMapping {
  key: string;
  expression: string;
}

export function TransformNodeInspector({
  node,
  onUpdate,
}: TransformNodeInspectorProps): React.ReactElement {
  const data = node.data as Record<string, unknown>;
  const config = (data.config as Record<string, unknown>) || {};
  const mappings = (config.mappings as FieldMapping[]) || [];

  const updateMappings = (newMappings: FieldMapping[]) => {
    onUpdate(node.id, {
      ...data,
      config: { ...config, mappings: newMappings },
    });
  };

  const addMapping = () => {
    updateMappings([...mappings, { key: '', expression: '' }]);
  };

  const removeMapping = (idx: number) => {
    updateMappings(mappings.filter((_, i) => i !== idx));
  };

  const updateMapping = (idx: number, field: 'key' | 'expression', value: string) => {
    const newMappings = [...mappings];
    newMappings[idx] = { ...newMappings[idx], [field]: value };
    updateMappings(newMappings);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <Label className="text-xs">Field Mappings</Label>
        <Button variant="ghost" size="sm" onClick={addMapping}>
          <Icon icon="plus" size="xs" className="mr-1" />
          Add Field
        </Button>
      </div>

      {mappings.length === 0 ? (
        <p className="text-xs text-foreground-tertiary">
          No field mappings defined. Add fields to transform the input data.
        </p>
      ) : (
        <div className="space-y-2">
          {mappings.map((mapping, idx) => (
            <div key={`mapping-${idx}`} className="flex gap-1 items-start">
              <div className="flex-1 space-y-1">
                <Input
                  value={mapping.key}
                  onChange={(e) => updateMapping(idx, 'key', e.target.value)}
                  placeholder="outputField"
                  className="text-xs"
                />
                <Input
                  value={mapping.expression}
                  onChange={(e) => updateMapping(idx, 'expression', e.target.value)}
                  placeholder="{{input.field}}"
                  className="text-xs font-mono"
                />
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => removeMapping(idx)}
                className="mt-0.5"
              >
                <Icon icon="x" size="xs" />
              </Button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

