/**
 * Data mapping utilities for workflow execution
 * Resolves template expressions like {{nodeId.output.path}} using the execution context
 */

type ContextMap = Map<string, unknown>;

/**
 * Resolve a template string by replacing {{nodeId.output.path}} expressions
 * with actual values from the execution context
 */
export function resolveTemplate(
  template: string,
  context: ContextMap,
  currentInput: unknown
): unknown {
  // If the entire string is a single template expression, return the raw value (not stringified)
  const singleMatch = template.match(/^\{\{(.+?)\}\}$/);
  if (singleMatch) {
    return resolveExpression(singleMatch[1].trim(), context, currentInput);
  }

  // Otherwise, replace all expressions with stringified values
  return template.replace(/\{\{(.+?)\}\}/g, (_match, expression: string) => {
    const value = resolveExpression(expression.trim(), context, currentInput);
    if (value === undefined || value === null) return '';
    if (typeof value === 'object') return JSON.stringify(value);
    return String(value);
  });
}

/**
 * Resolve a dot-path expression against the context
 * Supports: input.field, nodeId.output.path, nodeId.field
 */
function resolveExpression(
  expression: string,
  context: ContextMap,
  currentInput: unknown
): unknown {
  // "input" refers to the current node's resolved input
  if (expression === 'input') {
    return currentInput;
  }
  if (expression.startsWith('input.')) {
    return getNestedValue(currentInput, expression.slice(6));
  }

  // Otherwise, first segment is a nodeId
  const dotIndex = expression.indexOf('.');
  if (dotIndex === -1) {
    return context.get(expression);
  }

  const nodeId = expression.slice(0, dotIndex);
  const path = expression.slice(dotIndex + 1);

  const nodeOutput = context.get(nodeId);
  if (nodeOutput === undefined) return undefined;

  // If path starts with "output.", skip it
  const effectivePath = path.startsWith('output.') ? path.slice(7) : path;
  if (effectivePath === 'output' || effectivePath === '') return nodeOutput;

  return getNestedValue(nodeOutput, effectivePath);
}

/**
 * Get a nested value from an object using dot notation
 */
function getNestedValue(obj: unknown, path: string): unknown {
  const parts = path.split('.');
  let current = obj;

  for (const part of parts) {
    if (current === null || current === undefined) return undefined;
    if (typeof current !== 'object') return undefined;

    // Handle array indexing
    if (Array.isArray(current)) {
      const index = Number.parseInt(part, 10);
      if (Number.isNaN(index)) return undefined;
      current = current[index];
    } else {
      current = (current as Record<string, unknown>)[part];
    }
  }

  return current;
}

/**
 * Resolve all template values in an object/params recursively
 */
export function resolveParams(
  params: Record<string, unknown>,
  context: ContextMap,
  currentInput: unknown
): Record<string, unknown> {
  const resolved: Record<string, unknown> = {};

  for (const [key, value] of Object.entries(params)) {
    if (typeof value === 'string' && value.includes('{{')) {
      resolved[key] = resolveTemplate(value, context, currentInput);
    } else if (value && typeof value === 'object' && !Array.isArray(value)) {
      resolved[key] = resolveParams(value as Record<string, unknown>, context, currentInput);
    } else {
      resolved[key] = value;
    }
  }

  return resolved;
}

/**
 * Workflow Execution Engine
 *
 * Executes a workflow by:
 * 1. Loading the workflow with nodes and edges
 * 2. Topological sorting to determine execution order
 * 3. Executing nodes level-by-level (parallel within each level)
 * 4. Resolving data mappings between nodes
 */

import { prisma } from '@tpmjs/db';
import { topologicalSort, getUpstreamNodes } from './topological-sort';
import { resolveParams } from './data-mapping';
import { executeTrigger } from './node-executors/trigger';
import { executeTool } from './node-executors/tool';
import { executeAgent } from './node-executors/agent';
import { executeCondition } from './node-executors/condition';
import { executeLoop } from './node-executors/loop';
import { executeTransform } from './node-executors/transform';
import { executeOutput } from './node-executors/output';

export interface WorkflowExecutionResult {
  success: boolean;
  output?: unknown;
  error?: string;
}

type NodeStatusCallback = (
  nodeId: string,
  status: 'running' | 'completed' | 'failed' | 'skipped',
  output?: unknown,
  error?: string
) => void;

interface WorkflowNode {
  id: string;
  nodeId: string;
  type: string;
  label: string;
  config: Record<string, unknown> | null;
  toolId: string | null;
  agentId: string | null;
}

interface WorkflowEdge {
  id: string;
  edgeId: string;
  sourceNodeId: string;
  targetNodeId: string;
  sourceNode: { nodeId: string };
  targetNode: { nodeId: string };
  sourceHandle: string | null;
  targetHandle: string | null;
  dataMapping: Record<string, unknown> | null;
}

export async function executeWorkflow(
  workflowId: string,
  triggerInput: Record<string, unknown>,
  _userId: string,
  onNodeStatus: NodeStatusCallback
): Promise<WorkflowExecutionResult> {
  try {
    // Load the workflow with all nodes and edges
    const workflow = await prisma.workflow.findUnique({
      where: { id: workflowId },
      include: {
        nodes: true,
        edges: {
          include: {
            sourceNode: { select: { nodeId: true } },
            targetNode: { select: { nodeId: true } },
          },
        },
      },
    });

    if (!workflow) {
      return { success: false, error: 'Workflow not found' };
    }

    if (workflow.nodes.length === 0) {
      return { success: false, error: 'Workflow has no nodes' };
    }

    // Build a map from DB node records using their React Flow nodeId
    const nodeMap = new Map<string, WorkflowNode>();
    for (const node of workflow.nodes) {
      nodeMap.set(node.nodeId, {
        id: node.id,
        nodeId: node.nodeId,
        type: node.type,
        label: node.label,
        config: node.config as Record<string, unknown> | null,
        toolId: node.toolId,
        agentId: node.agentId,
      });
    }

    // Build edges using React Flow nodeIds
    const rfEdges = (workflow.edges as unknown as WorkflowEdge[]).map((e) => ({
      source: e.sourceNode.nodeId,
      target: e.targetNode.nodeId,
      sourceHandle: e.sourceHandle,
    }));

    // Topological sort
    const sortedNodes = Array.from(nodeMap.values()).map((n) => ({
      id: n.nodeId,
    }));
    const levels = topologicalSort(sortedNodes, rfEdges);

    // Execution context: maps nodeId -> output
    const context = new Map<string, unknown>();

    // Track which branches are active (for condition nodes)
    const activeBranches = new Map<string, string>();

    let finalOutput: unknown;

    // Execute level by level
    for (const level of levels) {
      await Promise.all(
        level.map(async (nodeId) => {
          const node = nodeMap.get(nodeId);
          if (!node) return;

          // Check if this node should be skipped (condition branch routing)
          const upstreamEdges = rfEdges.filter((e) => e.target === nodeId);
          const shouldSkip = upstreamEdges.some((edge) => {
            if (!edge.sourceHandle) return false;
            const activeBranch = activeBranches.get(edge.source);
            return activeBranch !== undefined && activeBranch !== edge.sourceHandle;
          });

          if (shouldSkip) {
            onNodeStatus(nodeId, 'skipped');
            return;
          }

          onNodeStatus(nodeId, 'running');

          try {
            // Resolve input from upstream nodes
            const upstreamNodes = getUpstreamNodes(nodeId, rfEdges);
            let input: unknown;

            if (upstreamNodes.length === 1) {
              input = context.get(upstreamNodes[0].sourceId);
            } else if (upstreamNodes.length > 1) {
              // Merge multiple upstream outputs
              const merged: Record<string, unknown> = {};
              for (const upstream of upstreamNodes) {
                merged[upstream.sourceId] = context.get(upstream.sourceId);
              }
              input = merged;
            } else if (node.type === 'TRIGGER') {
              input = triggerInput;
            }

            // Resolve config params with template expressions
            const config = node.config || {};
            const resolvedConfig =
              config && typeof config === 'object'
                ? resolveParams(config, context, input)
                : config;

            // Execute the node based on type
            let output: unknown;
            switch (node.type) {
              case 'TRIGGER':
                output = await executeTrigger(resolvedConfig, input);
                break;
              case 'TOOL':
                if (!node.toolId) throw new Error('Tool node has no tool configured');
                output = await executeTool(resolvedConfig, input, node.toolId);
                break;
              case 'AGENT':
                if (!node.agentId) throw new Error('Agent node has no agent configured');
                output = await executeAgent(resolvedConfig, input, node.agentId);
                break;
              case 'CONDITION': {
                const condResult = await executeCondition(resolvedConfig, input);
                output = condResult;
                activeBranches.set(nodeId, condResult.branch);
                break;
              }
              case 'LOOP':
                output = await executeLoop(resolvedConfig, input);
                break;
              case 'TRANSFORM':
                output = await executeTransform(resolvedConfig, input);
                break;
              case 'OUTPUT':
                output = await executeOutput(resolvedConfig, input);
                finalOutput = output;
                break;
              case 'NOTE':
                // Notes don't execute
                output = input;
                break;
              default:
                throw new Error(`Unknown node type: ${node.type}`);
            }

            context.set(nodeId, output);
            onNodeStatus(nodeId, 'completed', output);
          } catch (err) {
            const errorMessage = err instanceof Error ? err.message : String(err);
            onNodeStatus(nodeId, 'failed', undefined, errorMessage);
            throw err;
          }
        })
      );
    }

    return {
      success: true,
      output: finalOutput ?? context.get(Array.from(context.keys()).pop() || ''),
    };
  } catch (err) {
    return {
      success: false,
      error: err instanceof Error ? err.message : String(err),
    };
  }
}

/**
 * Agent node executor - one-shot text generation using an agent configuration
 */
import { prisma } from '@tpmjs/db';
import { generateText } from 'ai';
import { resolveTemplate } from '../data-mapping';

// Lazy model resolution to avoid importing all SDKs at once
async function getModel(provider: string, modelId: string) {
  switch (provider) {
    case 'OPENAI': {
      const { openai } = await import('@ai-sdk/openai');
      return openai(modelId);
    }
    case 'ANTHROPIC': {
      const { anthropic } = await import('@ai-sdk/anthropic');
      return anthropic(modelId);
    }
    case 'GOOGLE': {
      const { google } = await import('@ai-sdk/google');
      return google(modelId);
    }
    case 'GROQ': {
      const { groq } = await import('@ai-sdk/groq');
      return groq(modelId);
    }
    case 'MISTRAL': {
      const { mistral } = await import('@ai-sdk/mistral');
      return mistral(modelId);
    }
    default:
      throw new Error(`Unsupported provider: ${provider}`);
  }
}

export async function executeAgent(
  config: Record<string, unknown>,
  input: unknown,
  agentId: string
): Promise<unknown> {
  const agent = await prisma.agent.findUnique({
    where: { id: agentId },
    select: {
      provider: true,
      modelId: true,
      systemPrompt: true,
      temperature: true,
    },
  });

  if (!agent) {
    throw new Error(`Agent not found: ${agentId}`);
  }

  // Resolve prompt template
  let prompt = (config.prompt as string) || '';
  if (prompt.includes('{{')) {
    const resolved = resolveTemplate(prompt, new Map(), input);
    prompt = typeof resolved === 'string' ? resolved : JSON.stringify(resolved);
  }

  // If no prompt configured, use the input as the prompt
  if (!prompt && input) {
    prompt = typeof input === 'string' ? input : JSON.stringify(input);
  }

  const model = await getModel(agent.provider, agent.modelId);

  const result = await generateText({
    model,
    system: agent.systemPrompt || undefined,
    prompt,
    temperature: agent.temperature ?? 0.7,
    maxTokens: 4096,
  });

  return {
    text: result.text,
    usage: result.usage,
  };
}

import { Prisma, prisma } from '@tpmjs/db';
import type { NextRequest } from 'next/server';
import { z } from 'zod/v4';

import { logActivity } from '~/lib/activity';
import { authenticateRequest } from '~/lib/api-keys/middleware';
import {
  apiForbidden,
  apiInternalError,
  apiNotFound,
  apiSuccess,
  apiUnauthorized,
  apiValidationError,
  apiConflict,
} from '~/lib/api-response';

export const runtime = 'nodejs';
export const maxDuration = 60;

type RouteContext = {
  params: Promise<{ id: string }>;
};

const UpdateWorkflowSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  description: z.string().max(2000).optional().nullable(),
  status: z.enum(['DRAFT', 'ACTIVE', 'ARCHIVED']).optional(),
  triggerType: z.enum(['MANUAL', 'WEBHOOK', 'SCHEDULE']).optional(),
  triggerConfig: z.record(z.unknown()).optional().nullable(),
  envVars: z.record(z.unknown()).optional().nullable(),
});

/**
 * GET /api/workflows/[id]
 * Get a single workflow with its nodes and edges
 */
export async function GET(_request: NextRequest, context: RouteContext) {
  const requestId = crypto.randomUUID();

  try {
    const authResult = await authenticateRequest();
    if (!authResult.authenticated || !authResult.userId) {
      return apiUnauthorized('Authentication required', requestId);
    }

    const { id } = await context.params;

    const workflow = await prisma.workflow.findUnique({
      where: { id },
      include: {
        nodes: {
          orderBy: { createdAt: 'asc' },
          include: {
            tool: {
              select: {
                id: true,
                name: true,
                description: true,
                inputSchema: true,
                package: {
                  select: {
                    npmPackageName: true,
                    category: true,
                  },
                },
              },
            },
            agent: {
              select: {
                id: true,
                uid: true,
                name: true,
                description: true,
                provider: true,
                modelId: true,
              },
            },
          },
        },
        edges: {
          orderBy: { createdAt: 'asc' },
        },
        _count: {
          select: {
            nodes: true,
            edges: true,
            executions: true,
          },
        },
      },
    });

    if (!workflow) {
      return apiNotFound('Workflow', requestId);
    }

    if (workflow.userId !== authResult.userId) {
      return apiForbidden('Access denied', requestId);
    }

    return apiSuccess(
      {
        ...workflow,
        nodeCount: workflow._count.nodes,
        edgeCount: workflow._count.edges,
        executionCount: workflow._count.executions,
        _count: undefined,
      },
      { requestId }
    );
  } catch (error) {
    console.error('Failed to get workflow:', error);
    return apiInternalError('Failed to get workflow', requestId);
  }
}

/**
 * PATCH /api/workflows/[id]
 * Update workflow metadata
 */
export async function PATCH(request: NextRequest, context: RouteContext) {
  const requestId = crypto.randomUUID();

  try {
    const authResult = await authenticateRequest();
    if (!authResult.authenticated || !authResult.userId) {
      return apiUnauthorized('Authentication required', requestId);
    }

    const { id } = await context.params;
    const body = await request.json();
    const parsed = UpdateWorkflowSchema.safeParse(body);
    if (!parsed.success) {
      return apiValidationError(
        'Invalid request body',
        { errors: parsed.error.flatten().fieldErrors },
        requestId
      );
    }

    // Check ownership
    const existing = await prisma.workflow.findUnique({
      where: { id },
      select: { userId: true },
    });
    if (!existing) {
      return apiNotFound('Workflow', requestId);
    }
    if (existing.userId !== authResult.userId) {
      return apiForbidden('Access denied', requestId);
    }

    // Check name uniqueness if being changed
    if (parsed.data.name) {
      const existingByName = await prisma.workflow.findFirst({
        where: { userId: authResult.userId, name: parsed.data.name, id: { not: id } },
      });
      if (existingByName) {
        return apiConflict('A workflow with this name already exists', requestId);
      }
    }

    // Build update data
    const { triggerConfig, envVars, ...restData } = parsed.data;
    const updateData: Prisma.WorkflowUpdateInput = {
      ...restData,
      ...(triggerConfig !== undefined && {
        triggerConfig: triggerConfig === null ? Prisma.JsonNull : triggerConfig,
      }),
      ...(envVars !== undefined && {
        envVars: envVars === null ? Prisma.JsonNull : envVars,
      }),
    };

    const workflow = await prisma.workflow.update({
      where: { id },
      data: updateData,
      select: {
        id: true,
        uid: true,
        name: true,
        description: true,
        status: true,
        triggerType: true,
        triggerConfig: true,
        version: true,
        createdAt: true,
        updatedAt: true,
      },
    });

    // Log activity (fire-and-forget)
    logActivity({
      userId: authResult.userId,
      type: 'WORKFLOW_UPDATED',
      targetName: workflow.name,
      targetType: 'workflow',
    });

    return apiSuccess(workflow, { requestId });
  } catch (error) {
    console.error('Failed to update workflow:', error);
    return apiInternalError('Failed to update workflow', requestId);
  }
}

/**
 * DELETE /api/workflows/[id]
 * Delete a workflow and all its nodes, edges, and executions (cascade)
 */
export async function DELETE(_request: NextRequest, context: RouteContext) {
  const requestId = crypto.randomUUID();

  try {
    const authResult = await authenticateRequest();
    if (!authResult.authenticated || !authResult.userId) {
      return apiUnauthorized('Authentication required', requestId);
    }

    const { id } = await context.params;

    // Check ownership and get name for activity log
    const existing = await prisma.workflow.findUnique({
      where: { id },
      select: { userId: true, name: true },
    });
    if (!existing) {
      return apiNotFound('Workflow', requestId);
    }
    if (existing.userId !== authResult.userId) {
      return apiForbidden('Access denied', requestId);
    }

    await prisma.workflow.delete({ where: { id } });

    // Log activity (fire-and-forget)
    logActivity({
      userId: authResult.userId,
      type: 'WORKFLOW_DELETED',
      targetName: existing.name,
      targetType: 'workflow',
    });

    return apiSuccess({ deleted: true }, { requestId });
  } catch (error) {
    console.error('Failed to delete workflow:', error);
    return apiInternalError('Failed to delete workflow', requestId);
  }
}

import { prisma } from '@tpmjs/db';
import type { NextRequest } from 'next/server';
import { z } from 'zod/v4';

import { authenticateRequest } from '~/lib/api-keys/middleware';
import {
  apiForbidden,
  apiInternalError,
  apiNotFound,
  apiSuccess,
  apiUnauthorized,
  apiValidationError,
} from '~/lib/api-response';

export const runtime = 'nodejs';
export const maxDuration = 60;

type RouteContext = {
  params: Promise<{ id: string }>;
};

const NodeSchema = z.object({
  nodeId: z.string().max(100),
  type: z.enum(['TRIGGER', 'TOOL', 'AGENT', 'CONDITION', 'LOOP', 'TRANSFORM', 'OUTPUT', 'NOTE']),
