      // Create new nodes
      if (nodes.length > 0) {
        await tx.workflowNode.createMany({
          data: nodes.map((node) => ({
            workflowId: id,
            nodeId: node.nodeId,
            type: node.type,
            label: node.label,
            positionX: node.positionX,
            positionY: node.positionY,
            config: node.config ?? undefined,
            toolId: node.toolId ?? undefined,
            agentId: node.agentId ?? undefined,
